const aftermathVoices={"서이준":{"days":12,"mode":"거리 두기","l":["…알겠어요. 제가 더 할 말은 없는 것 같네요.","이준이 잠시 시선을 돌렸다. 평소보다 인사가 짧았다.","…조금 혼자 있고 싶었어요. 누구 잘못이라서 그런 건 아니고요.","…이제는 편하게 지낼 수 있을 것 같아요. 고양이 얘기 정도는 해도 되죠?","예전처럼 편한 이웃으로 지내고 싶어요.","…그래요. 그 정도가 지금은 좋겠네요.","조금 더 시간을 가져요.","네. 나중에 봐요.","급식소 지붕을 고쳤어요. 지나가다가 보면 알 거예요."]},"강도윤":{"days":7,"mode":"웃음 뒤의 실연","l":["하하… 그렇군요. 제 마음을 들어 주신 것만으로도 고마워요.","도윤은 웃으며 잔을 닦았다. 빈 잔을 한참 들고 있었다.","사실 괜찮은 척하고 있었어요. 저도 좀 아쉬워할 수 있는 거잖아요.","이제는 손님도 연애 상대도 아닌 친구로 편하게 만나고 싶네요.","도윤 씨도 자신의 마음을 소중히 여겼으면 해요.","……고마워요. 저도 제 일상을 잘 돌볼게요.","서로 조금 더 쉬어 가요.","좋아요. 모카랑 산책 좀 하고 올게요.","새 원두를 골라 봤어요. 다음에 카페 들르면 맛봐요."]},"한시우":{"days":5,"mode":"농담으로 감추기","l":["아… 오케이. 이번엔 제가 진 거네요. 아니, 이런 말 하면 안 되나.","시우가 웃으려다 들고 있던 게임기를 내려놓았다.","진짜 아무렇지 않은 척하려니까 좀 어렵네요. 그래도 게임처럼 이기고 지는 건 아니죠.","오예, 다시 게임 친구 해도 되는 거죠? 이번엔 랭크 없이!","승부 말고 친구로 같이 놀아요.","콜! 진짜 이번엔 재미로 해요.","오늘은 각자 시간 보내요.","오케이. 연습하고 올게요.","신작 게임 나왔어요! 혼자 해 봤는데 생각보다 재밌음."]},"백지한":{"days":14,"mode":"미련과 자존심","l":["…그렇군요. 제가 원한다고 해서 당신 마음까지 정할 수는 없죠.","지한은 미소를 지었지만 평소처럼 말을 이어 가지 않았다.","솔직히 아쉬워요. 제가 더 특별한 사람이 되고 싶었거든요. 그건 제가 정리할 문제죠.","이제는 뭘 바라면서 만나고 싶지 않아요.","서로 부담 없는 사이로 지내요.","좋아요. 그 말의 의미를 잊지 않을게요.","아직은 조금 떨어져 지내요.","…알겠어요. 먼저 붙잡지 않을게요.","동네에 괜찮은 건물 하나 생겼더라고요. 지나가면서 구경해 봐요."]},"정태오":{"days":4,"mode":"정중한 수용","l":["알겠습니다. 마음을 말씀해 주셔서 감사합니다. 선택을 존중하겠습니다.","태오가 가볍게 고개를 숙였다.","저도 정리할 시간이 조금 필요했습니다. 불편하게 만들 생각은 없습니다.","앞으로도 서로 안부를 나눌 수 있다면 좋겠습니다.","편한 이웃으로 계속 인사해요.","알겠습니다. 그렇게 지내도록 하지요.","시간을 더 갖는 게 좋겠어요.","네. 무리하지 마십시오.","강변 길이 정비되었습니다. 산책하실 때 참고하십시오."]},"임하나":{"days":10,"mode":"조용한 아쉬움","l":["……네. 제 마음을 말해 볼 수 있어서 좋았어요. 대답해 주셔서 감사해요.","하나가 소매 끝을 만지며 작게 웃었다.","저도 아쉬워요. 그래도 제가 좋아하는 일까지 그만둘 필요는 없겠죠.","저… 이제는 저 자신을 위해 하고 싶은 일도 찾아보려고요. 친구로 이야기해도 될까요?","하나 씨가 원하는 걸 계속 찾아가요.","네. 저도 제 이야기를 더 많이 만들어 볼게요.","조금 더 시간을 가져요.","……네. 저도 천천히 정리할게요.","보고 싶었던 책을 드디어 샀어요. 제 돈으로 제가 고른 책이에요."]},"차유리":{"days":3,"mode":"독립적인 우정","l":["오, 그렇군요. 마음이 같지 않을 수도 있죠. 솔직히 말해 줘서 고마워요.","유리가 스케치북을 가방에 넣고 잠시 창밖을 봤다.","아쉽긴 한데 그렇다고 제 작업이나 친구까지 잃을 생각은 없어요.","이제 서로 그림 얘기하고 편하게 놀면 좋겠네요.","좋아요. 친구로도 서로 응원해요.","오케이. 그럼 신작 나오면 보여 줄게요.","당분간 각자 시간을 가져요.","좋아요. 저도 작업 좀 밀렸거든요.","새 작업 시작했어요. 이번엔 제가 좋아하는 색만 써 보려고요."]},"오세린":{"days":3,"mode":"차분한 수용","l":["아아, 그렇군요. 마음을 강요할 수는 없죠. 말씀해 주셔서 고마워요.","세린이 잠시 찻잔을 내려놓았다가 부드럽게 미소 지었다.","으음, 아쉬운 마음도 천천히 지나가겠지요. 우리 둘 다 편안했으면 좋겠어요.","앞으로도 가끔 차를 함께 마실 수 있으면 좋겠네요.","서로 편한 친구로 지내요.","네. 그 관계도 충분히 소중하죠.","조금 더 여유를 가져요.","아아, 그렇게 해요. 편히 지내세요.","새 허브차를 들였어요. 향이 좋아서 추천하고 싶었네요."]},"유지안":{"days":6,"mode":"실망을 인정하기","l":["……아, 그렇군요. 괜찮아요! 아니, 조금 아쉽긴 하네요. 솔직히.","지안이 평소보다 작은 목소리로 인사했다.","기대했으니까 속상하기도 해요. 그래도 좋아했던 마음 자체가 잘못된 건 아니잖아요.","이제는 같이 웃을 수 있는 친구로 지내고 싶어요.","좋아요. 서로 하고 싶은 일을 응원해요.","예쓰! 저도 다음 공연 준비할게요.","잠깐 각자 마음을 정리해요.","넵. 저도 연습하면서 머리 좀 식힐게요.","새 안무 만들었어요! 이번엔 완전 제 취향으로요."]},"공재희":{"days":15,"mode":"미련과 불안","l":["아… 웅. 알겠어요. 나 좀 생각할 시간이 필요함.","재희가 휴대전화를 쥐고 잠시 고개를 숙였다.","나 괜히 예전 톡 계속 봤어요. 그만 봐야 하는 거 아는데 좀 어려웠음.","웅… 이제는 친구로 이야기해도 괜찮을 것 같아요. 나도 내 방송 잘 하고 싶고.","친구로 지낼 수 있으면 좋겠어요.","웅. 그럼 웃긴 짤 발견하면 보내도 돼요? …오늘은 하나만 보낼게요.","당분간 각자의 시간을 보내요.","…웅. 나 먼저 연락 안 하고 좀 쉬어 볼게요.","새 방송 배경 꾸몄어요ㅋㅋ 이번엔 내가 좋아하는 걸로만 채움."]}};
const romanceProfiles={"서이준":[185,8,0,"…좋아해요. 이제는 그냥 이웃으로만 보고 싶지 않아요.","…저는 한 사람과 서로 약속하는 관계가 좋아요.","…서로 알고 선택하는 거라면, 생각해 볼게요.","…알겠어요. 더 붙잡진 않을게요.","…그동안 저한테 했던 말은 뭐였어요? 지금은 혼자 있고 싶어요.","책방에 들렀다가 강변 걷는 건 어때요?"],"강도윤":[155,7,1,"저도 이제는 챙겨 드리고 싶은 사람 이상으로 만나고 싶어요. 저랑 사귀어 주실래요?","하하… 저는 지금은 한 사람과 만나는 게 편할 것 같아요.","서로의 마음을 감추지 않고 모두가 원한다면 저도 그렇게 만나 볼게요.","……아쉽지만 마음을 억지로 붙잡을 순 없죠.","웃으면서 넘길 수 있는 이야기는 아니네요. 저도 상처받았어요.","하하, 간식은 각자 먹고 싶은 걸 골라요."],"한시우":[130,8,1,"장난 아니에요. 나 진짜 좋아해요. 우리 사귈래요?","아… 저는 그건 아직 좀 어려울 듯해요.","오, 셋 다 솔직하게 얘기할 수 있으면 해 보고 싶어요. 누구도 억지로 끌려오는 건 아니고요!","아… 오케이. 그럼 좀 연습하고 올게요.","와, 이건 농담으로 못 넘기겠는데요. 잠깐 생각 좀 할게요.","오예! 셋이서 할 수 있는 게임 찾아봐요."],"정태오":[210,10,0,"좋아합니다. 앞으로 연인으로 만나 뵙고 싶습니다.","죄송합니다. 저는 한 사람과의 교제를 원합니다.","서로 명확히 합의했다면 존중하겠습니다.","알겠습니다. 마음이 바뀌었다는 사실을 받아들이겠습니다.","신뢰에 관한 문제입니다. 지금은 관계를 다시 생각해야겠습니다.","서두르지 않고 천천히 걸으시죠."],"백지한":[115,7,0,"이젠 제가 먼저 물어볼래요. 저랑 만나 줄래요?","…저는 우리 둘만 사귀고 싶어요. 그건 양보하기 어렵네요.","서로가 선택한 관계여야겠죠.","이유는 알고 싶지만 마음을 강요할 순 없겠죠.","…제가 모르는 사이에 다른 연인까지 있었군요. 지금 웃으면서 넘어갈 수는 없어요.","각자 보고 싶은 곳을 하나씩 고르죠."],"임하나":[175,7,0,"저… 제가 원하는 걸 처음으로 말해 보고 싶어요. 좋아해요. 저랑 만나 주실래요?","……저는 그런 관계를 원하지 않아요. 제 마음도 존중해 주세요.","모두 괜찮다고 한다면 생각해 볼 수는 있어요.","……네. 저도 제 마음을 돌볼게요.","……제가 몰랐던 일이 있었네요. 오늘은 혼자 생각하고 싶어요.","저도 제가 먹고 싶은 간식을 먼저 골라 볼래요."],"차유리":[160,8,2,"저 좋아해요. 우리 각자 하던 일도 잘하면서 만나 볼래요?","아, 그 관계는 지금 제 마음과는 좀 달라요.","좋아요. 누구도 강요받지 않고 솔직하게 이야기할 수 있다면요.","마음은 변할 수 있죠. 저도 제 일상을 챙길게요.","합의하지 않은 관계를 숨긴 건 다른 문제잖아요. 이건 좀 생각해야겠네요.","오, 각자 마음에 드는 풍경 찍고 사진 비교해요!"],"오세린":[190,8,1,"같이 보내는 시간이 좀 더 많았으면 좋겠어요. 저랑 만나 볼래요?","으음, 저는 지금은 그런 형태의 연애를 바라지 않아요.","서로 충분히 이야기했고 모두가 원한다면 함께 알아가도 좋겠네요.","네. 마음을 솔직히 전해 주셔서 고마워요.","아아… 서로 합의하지 않은 일이었군요. 신뢰를 다시 생각해야겠네요.","차 한잔씩 골라서 천천히 이야기해요."],"유지안":[145,7,2,"저 이번엔 기대하는 걸 숨기지 않을래요. 좋아해요! 우리 사귈래요?","앗… 저는 아직 그런 관계는 준비가 안 된 것 같아요.","좋아요! 서로의 마음이랑 일정, 전부 존중하는 거예요.","……아쉽지만 제 마음도 잘 챙길게요.","와… 저 진짜 괜찮은 척 못 하겠어요. 조금 시간 주세요.","예쓰! 오늘은 셋 다 한 곡씩 플레이리스트에 넣어요."],"공재희":[120,7,0,"나 진짜 좋아해요. 우리 사귀면 안 돼요?","아… 나 아직은 다른 애인이 있는 관계는 못 할 것 같음.","웅… 서로 진짜 괜찮은지 먼저 말해 봐요.","웅. 나 좀 혼자 있고 싶어요.","아… 나 몰랐던 거네요. 지금은 말 더 못 하겠음.","셋이 사진 찍을래요? 각자 고른 포즈로ㅋㅋ"]};
function lovers(){const v=initSim();return people.filter(p=>v.romance[p]==='dating')}
const lifeEndingText={"first":["첫 마음, 다음 계절","처음 마음을 나눈 사람과 한 해의 마지막 날까지 함께했다. 처음의 설렘과는 다른, 익숙하고도 새로운 내일이 기다리고 있다."],"new":["다시 피어난 계절","지나간 관계는 사라지지 않았다. 그 시간들을 지나 지금 곁에 있는 사람과 새로운 계절을 맞이한다."],"reunion":["다시 시작한 우리","한번 멀어졌던 두 사람이 다시 서로를 선택했다. 예전으로 돌아가는 것이 아니라, 그때와는 다른 관계를 만들어 갈 것이다."],"agreed":["함께 선택한 내일","두 사람은 각자 당신의 연인이다. 서로의 존재를 인정하며, 각자의 마음과 시간을 존중할 새로운 한 해를 준비한다."],"tension":["아직 맞춰 가는 세 사람","서로 동의한 관계였지만 모든 서운함이 해결된 것은 아니다. 세 사람의 내일에는 아직 나누어야 할 이야기가 남아 있다."],"secret":["엇갈린 두 마음","서로에게 전하지 못한 진실이 남아 있다. 한 해가 끝났다고 선택의 결과까지 사라지는 것은 아니다."],"revealed":["말하지 못했던 진실","숨겨 왔던 관계가 드러난 뒤에도 아직 답을 찾지 못했다. 새해의 첫날에는 무엇보다 솔직한 대화가 필요할 것이다."],"solo":["나의 새로운 시작","누군가의 연인이 되지 않았어도 이곳에서 보낸 시간은 당신의 것이다. 새로운 계절을 자신의 속도로 맞이한다."],"healed":["사랑이 지나간 자리","한때 마음을 나누었던 사람들과의 기억을 품고, 이제는 홀로 다음 계절을 맞이한다. 끝난 관계도 살아온 시간의 일부다."],"unresolved":["겨울 끝에 남은 편지","끝난 관계에 아직 다 하지 못한 말이 남아 있다. 그 마음을 어떻게 간직할지는 앞으로의 당신이 정할 일이다."],"strained":["아직 끝나지 않은 이야기","함께 새해를 맞지만 두 사람 사이에는 아직 풀리지 않은 마음이 있다. 내일은 서로에게 다시 귀 기울이는 날이 되기를."]};
const lifeAchievementList=[["firstLove","첫 번째 봄","처음으로 연인이 되었다."],["three","연화동의 인기인","서로 다른 세 사람과 교제했다."],["five","연화동의 카사노바","서로 다른 다섯 사람과 교제했다."],["ten","연화동의 전설","열 명 모두와 한 번 이상 교제했다."],["one","한 사람, 사계절","한 사람과만 교제하고 365일을 마쳤다."],["return","두 번째 첫사랑","헤어진 연인과 다시 교제했다."],["agreed","각자의 사랑","모두가 동의한 다자연애를 시작했다."],["group","셋이 걷는 길","합의된 다자연애 데이트를 마쳤다."],["secret","비밀의 계절","서로에게 알리지 않은 교제를 시작했다."],["revealed","연화동은 좁다","비밀 교제 사실이 드러났다."],["dumped","마지막 인사","NPC가 먼저 관계를 끝냈다."],["friend","사랑 이후에도","전 연인과 친구 관계를 다시 만들었다."],["solo","나만의 365일","연애하지 않고 365일을 마쳤다."],["healed","다음 페이지","이별 후 혼자인 상태로 한 해를 마쳤다."],["memory","남겨진 물건","전 연인에게 두고 온 물건을 돌려받았다."]];
function romanceHistorySummary(history,active){const h=history.filter(x=>x&&typeof x.p==='string'&&Number.isFinite(x.day)&&['start','end'].includes(x.kind)).slice().sort((a,b)=>a.day-b.day);const starts=h.filter(x=>x.kind==='start'),names=[...new Set([...starts.map(x=>x.p),...h.filter(x=>x.kind==='end').map(x=>x.p),...active])];return {history:h,starts:starts.length,names,ends:h.filter(x=>x.kind==='end').length,reunited:names.filter(p=>starts.filter(x=>x.p===p).length>1||h.some(x=>x.kind==='end'&&x.p===p)&&active.includes(p))}}
function annualRomanceSummary(){const v=initSim(),all=lovers(),h=romanceNetwork().history.slice();for(const p of people){const e=exRecord(p);if(e&&!h.some(x=>x.p===p&&x.kind==='end'))h.push({p,kind:'end',day:e.day,reason:e.reason});if(e&&!h.some(x=>x.p===p&&x.kind==='start'&&x.day<=e.day))h.push({p,kind:'start',day:e.since||300});if(all.includes(p)&&!h.some(x=>x.p===p&&x.kind==='start'&&x.day===(coupleRecord(p).since||300)))h.push({p,kind:'start',day:coupleRecord(p).since||300})}return romanceHistorySummary(h,all)}
function chooseLifeEnding(a){if(a.active.length>=2)return a.mode==='agreed'?(a.tension?'tension':'agreed'):a.revealed?'revealed':'secret';if(a.active.length===1)return a.tension?'strained':a.reunited.includes(a.active[0])?'reunion':a.names.length===1&&a.ends===0?'first':'new';return a.names.length?(a.unresolved?'unresolved':'healed'):'solo'}
function groupEndingText(code,n){
 if(n>2&&code==='agreed')return [lifeEndingText.agreed[0],'곁에 있는 연인들은 서로의 존재를 알고 각자의 마음을 선택했다. 함께 쌓아 온 시간이 다음 계절로 이어진다.'];
 if(n>2&&code==='tension')return ['아직 맞춰 가는 우리','서로 알고 선택한 관계에도 아직 나눠야 할 말이 남았다. 저마다의 마음을 안고 새로운 봄을 맞는다.'];
 if(n>2&&code==='secret')return ['엇갈린 마음들',lifeEndingText.secret[1]];
 return lifeEndingText[code];
}
function lifeEnding(){const v=initSim(),active=lovers(),h=annualRomanceSummary(),pairs=active.flatMap((p,i)=>active.slice(i+1).map(q=>pairState(p,q)).filter(Boolean)),tension=active.some(p=>!!coupleIssueRecord(p).active)||pairs.some(pair=>Object.values(pair.dynamic?.individual||{}).some(z=>z.need));const code=chooseLifeEnding({...h,active,mode:romanceMode(),revealed:pairs.some(pair=>Object.values(pair.known||{}).some(Boolean)&&pair.mode!=='agreed'),tension,unresolved:people.some(p=>v.romance[p]==='ended'&&aftermathRecord(p)?.status!=='friend')});const [title,line]=groupEndingText(code,active.length);return {code,title,line,active,summary:h}}
function awardLife(id,day=initSim().day){const a=lifeAchievementList.find(x=>x[0]===id);if(!a)return;const v=initSim();v.lifeAchievements=v.lifeAchievements||{};if(v.lifeAchievements[id])return;v.lifeAchievements[id]=day;albumUnlock('event','achievement:'+id,'',a[1],[['업적',a[2]]],day);writeJournal('업적 · '+a[1])}
function checkLifeAchievements(finished=false){const v=initSim(),a=annualRomanceSummary(),n=a.names.length,active=lovers(),history=romanceNetwork().history;if(n)awardLife('firstLove');if(n>=3)awardLife('three');if(n>=5)awardLife('five');if(n>=10)awardLife('ten');if(a.reunited.length)awardLife('return');if(active.length>=2&&romanceMode()==='agreed')awardLife('agreed');if(active.some((p,i)=>active.slice(i+1).some(q=>secretUnknown(p,q)||secretUnknown(q,p))))awardLife('secret');if(history.some(x=>x.kind==='revealed'))awardLife('revealed');if(people.some(p=>exRecord(p)?.initiator==='npc'))awardLife('dumped');if(people.some(p=>exRecord(p)&&aftermathRecord(p)?.status==='friend'))awardLife('friend');if(people.some(p=>exRecord(p)?.homeBelonging?.status==='returned'))awardLife('memory');if(finished){if(n===1&&a.ends===0&&active.length===1)awardLife('one');if(!n)awardLife('solo');if(n&&!active.length)awardLife('healed')}}
