function yearPartnerLines(row,day=365){
 const p=row.p,scene=yearPartnerScenes[p][row.unsettled?1:0];
 const line=scene[1+speechRegisterIndex(p,'npc',day)];
 return [['이야기',scene[0]],[p,spokenCall(p,'npc',day,line)]];
}

function coupleChapterEnding(e){
 if(e.active.length!==1||e.summary.names.length!==1||!['first','reunion'].includes(e.code))return null;
 const p=e.active[0],last=initSim().couple?.[p]?.chapters?.[2];
 if(!last)return null;
 const [title,opening,formal,casual,bold,quiet]=coupleChapterEndings[p];
 const lines=[['이야기',opening],[p,speechRegisterIndex(p,'npc',365)?casual:formal],['이야기',last.choice===0?bold:quiet]];
 return {p,title,lines};
}
function yearReady(v){
 return v.day>=365 && !!(v.finished||v.christmas?.endingDone) && !v.activeEvent;
}
function makeYearRecord(ev){
 const v=initSim(), ending=ev?.lifeEnding||lifeEnding(), career=ev?.careerEnding||annualCareerEnding();
 const partners=yearPartners(365);
 const development=developmentRecord();
 const goals=new Set(career.results);
 for(const [key,count] of Object.entries(development.completed)){
  const stages=developmentProjects[key]?.stages||[];
  let missing=count-stages.filter(stage=>goals.has(stage[2])).length;
  for(const stage of stages.slice(0,count)){
   if(missing<=0)break;
   if(!goals.has(stage[2])){goals.add(stage[2]);missing--}
  }
 }
 return {
  name:state.name, title:ending.title, line:ending.line, code:ending.code,
  partners:partners.map(row=>({name:row.p,days:row.days,lines:yearPartnerLines(row,365)})),
  featuredPartner:partners[0]?.p||null,
  friends:friendCandidates().filter(name=>!partners.some(row=>row.p===name)).map(name=>({name,line:friendFarewell(name,365)})),
  career:{title:career.title,line:career.line,profession:ev?.professionEnding||professionEnding()},
  job:state.job,money:v.money,energy:v.energy,fatigue:healthRecord().fatigue,
  skills:{...v.skills},inner:{...v.innerGrowth},traits:{...state.identity?.traits},
  goals:[...goals],memories:yearMemoExcerpt(v),achievements:lifeAchievementList.filter(([id])=>v.lifeAchievements?.[id]).map(([id,name,description])=>({name,description,day:v.lifeAchievements[id]})),
  page:'record'
 };
}
function finishYear(ev){
 const v=initSim();
 if(v.activeEvent!==ev)return;
 albumCapture(ev);
 christmasState().endingDone=true;
 v.finished=true;v.activeEvent=null;v.weekEnd=null;v.running=null;
 if(!v.yearBook)v.yearBook=makeYearRecord(ev);
 yearArchiveStore(v.yearBook);
 save();
 renderYearView('future');
}
function yearElement(parent,tag,content,className){
 const el=document.createElement(tag);
 if(className)el.className=className;
 if(content!=null)el.textContent=content;
 parent.append(el);
 return el;
}
function yearSection(parent,id,title){
 const block=yearElement(parent,'section',null,'year-section');
 block.id=id;
 yearElement(block,'h3',title);
 return block;
}
function yearButton(parent,id,label,run,secondary=false){
 const b=yearElement(parent,'button',label,secondary?'secondary':'');
 b.id=id;b.type='button';b.addEventListener('click',run);
}
function yearFigures(parent,entries){
 const dl=yearElement(parent,'dl',null,'year-figures');
 for(const [label,value] of entries){
  const cell=yearElement(dl,'div');yearElement(cell,'dt',label);yearElement(cell,'dd',value);
 }
}
function renderYearRecord(panel,b){
 const head=yearElement(panel,'div',null,'year-cover');
 yearElement(head,'small',b.name+'의 생활일지 · 2월 28일');
 yearElement(head,'h2','한 해의 결산').id='yearHeading';
 yearElement(head,'p',b.title,'year-ending-title');
 yearElement(head,'p',b.line);
 const partners=yearSection(panel,'yearPartners','마지막 날의 연인');
 if(b.partners.length){
  yearElement(partners,'p',b.partners.map(x=>x.name).join(' · '),'year-names');
  for(const person of b.partners){
   const detail=yearElement(partners,'details',null,'year-memory');
   yearElement(detail,'summary',person.name+'의 마지막 장면'+(person.days>0?' · 교제 '+person.days+'일째':''));
   for(const [speaker,line] of person.lines)yearElement(detail,'p',speaker===person.name?'“'+line+'”':line);
  }
 }else yearElement(partners,'p','마지막 날, 나는 연인 없이 한 해를 마쳤다.');
 if(b.friends.length){
  const friends=yearSection(panel,'yearFriends','오래 이어질 우정');
  for(const f of b.friends){
   const line=yearElement(friends,'p');yearElement(line,'b',f.name+'　');line.append(document.createTextNode('“'+f.line+'”'));
  }
 }
 const stats=yearSection(panel,'yearStats','나의 최종 스탯');
 yearFigures(stats,[['직업',b.job],['소지금',b.money.toLocaleString('ko-KR')+'원'],['체력',b.energy+'/100'],['누적 피로',b.fatigue+'/100']]);
 yearElement(stats,'h4','능력치');yearFigures(stats,Object.entries(b.skills));
 yearElement(stats,'h4','내면 성장');yearFigures(stats,Object.entries(b.inner));
 if(Object.keys(b.traits).length){yearElement(stats,'h4','성격');yearFigures(stats,Object.entries(b.traits))}
 const career=yearSection(panel,'yearCareer','일과 자기계발');
 yearElement(career,'h4',b.career.title);yearElement(career,'p',b.career.line);
 if(b.career.profession){
  const pr=b.career.profession;
  yearElement(career,'h4',(pr.ready?'이후의 이야기 · ':'앞으로의 목표 · ')+pr.name);yearElement(career,'p',pr.line);
 }
 yearElement(career,'h4','완성한 목표 · '+b.goals.length+'개');
 if(b.goals.length){
  const goals=yearElement(career,'ul',null,'year-goals');
  for(const goal of b.goals)yearElement(goals,'li',goal);
 }else yearElement(career,'p','이번 해에 완성한 자기계발 목표가 없다.');
 const achieved=yearSection(panel,'yearAchievements','이번 회차의 업적 · '+b.achievements.length+'개');
 if(b.achievements.length){
  const list=yearElement(achieved,'ul',null,'year-achievements');
  for(const a of b.achievements){
   const li=yearElement(list,'li');yearElement(li,'b',a.name);yearElement(li,'small','DAY '+a.day);yearElement(li,'p',a.description);
  }
 }else yearElement(achieved,'p','이번 회차에 획득한 업적이 없다.');
 yearStoryNav(panel,'record');
}
