 if(b.partners.length){yearElement(by,'h4','마지막 날까지 함께한 연인');yearElement(by,'p',b.partners.map(x=>x.name).join(' · '))}
 yearElement(by,'h4','연화동 사람들');yearElement(by,'p',people.join(' · '));
