 yearButton(panel,'yearRecordBack','한 해의 결산 다시 보기',()=>renderYearView('record'));
 yearButton(panel,'yearAlbumOpen','추억 앨범 열기',()=>{switchTab('album');$('album').querySelector('h2').scrollIntoView({block:'start'})},true);
