function renderYearView(page){
 const v=initSim();if(!yearReady(v))return;
 if(!v.yearBook){
  checkLifeAchievements(true);
  v.yearBook=makeYearRecord();save();
 }
 const b=v.yearBook;
 yearArchiveStore(b);
 page=['future','people','diary','record','credits'].includes(page)?page:'future';
 if(b.page!==page){b.page=page;save()}
 $('yearReopen').hidden=false;
 const panel=$('yearFinale');panel.replaceChildren();panel.dataset.page=page;
 if(page==='future')renderYearFuture(panel,b);
 else if(page==='people')renderYearPeople(panel,b);
 else if(page==='diary')renderYearDiary(panel,b);
 else if(page==='credits')renderYearCredits(panel,b);
 else renderYearRecord(panel,b);
 $('progress').textContent='365일 · '+b.title;
 $('where').textContent='연화빌라';$('clock').textContent='2월 28일 · DAY 365';
 switchTab('yearFinale');
 const heading=$('yearHeading');heading.tabIndex=-1;heading.focus({preventScroll:true});
 panel.scrollIntoView({block:'start'});
}
$('yearReopen').addEventListener('click',()=>renderYearView('record'));

function savedYearEnding(ev){
 const cached=ev.lifeEnding;
 if(!cached||!Array.isArray(cached.active)||!cached.summary)return ev.lifeEnding=lifeEnding();
 const names=yearPartners(ev.day??365).map(row=>row.p);
 if(names.length!==cached.active.length||names.some(name=>!cached.active.includes(name))){
  const current=lifeEnding();
  if(current.active.length===names.length)return ev.lifeEnding=current;
  cached.active=names;
 }
 if(names.length>2)[cached.title,cached.line]=groupEndingText(cached.code,names.length);
 return cached;
}
function lifeEndingRender(ev){const v=initSim(),e=savedYearEnding(ev);$('progress').textContent='365일 · '+e.title;add('이야기',e.title);add('이야기',e.line);const chapterEnd=coupleChapterEnding(e),partners=yearPartners(ev.day??365);
 if(partners.length){
  add('이야기','마지막 날에도 곁에 있는 연인 · '+partners.map(row=>row.p).join(', '));
  for(const row of partners){
   add('이야기',nameWith(row.p)+' 맞는 다음 계절');
   for(const [who,line] of yearPartnerLines(row,ev.day??365))add(who,line);
  }
 }
 if(chapterEnd){add('이야기','다음 봄 · '+chapterEnd.title);for(const [who,line] of chapterEnd.lines)add(who,line)}
 add('시스템','연화동 365일의 기록 · 교제한 사람 '+e.summary.names.length+'명 · 교제 시작 '+e.summary.starts+'회 · 이별 '+e.summary.ends+'회 · 재결합한 사람 '+e.summary.reunited.length+'명');const c=ev.careerEnding||(ev.careerEnding=annualCareerEnding());add('이야기','직업과 자기계발 · '+c.title);add('이야기',c.line);for(const result of c.results)add('시스템','완성한 목표 · '+result);add('이야기',c.balance);const friends=friendCandidates().filter(name=>!e.active.includes(name));if(friends.length){add('이야기','오래 이어질 우정');for(const p of friends)add(p,friendFarewell(p,ev.day??365))}const pr=ev.professionEnding||(ev.professionEnding=professionEnding());if(pr){add('이야기',pr.ready?'이후의 이야기 · '+pr.name:'앞으로의 목표 · '+pr.name);add('이야기',pr.line);for(const p of e.active){const scene=professionScene(pr,p);if(scene){add('이야기',scene[2]);add(p,formatSpeech(p,scene[3],'npc',undefined,ev.day??365))}}}add('시스템','현재 직업: '+state.job+' · 소지금 '+v.money.toLocaleString()+'원 · 자기계발 성취 '+c.summary.projects+'개');if(!v.yearBook){checkLifeAchievements(true);v.yearBook=makeYearRecord(ev);save()}choiceButton('한 해의 결산 보기',()=>finishYear(ev));setStoryStanding(null);$('log').scrollTop=0}

function romanceNetwork(){const v=initSim();return v.romanceNetwork||(v.romanceNetwork={pairs:{},history:[],offers:{},lastOffer:0})}
function pairKey(a,b){return [a,b].sort().join('|')}
function pairState(a,b){return romanceNetwork().pairs[pairKey(a,b)]||null}
function bothConsented(a,b){const x=pairState(a,b);return !!(x&&x.mode==='agreed'&&x.consent?.[a]===true&&x.consent?.[b]===true)}
function romanceMode(){const a=lovers();return a.length<2?'exclusive':a.every((p,i)=>a.slice(i+1).every(q=>bothConsented(p,q)))?'agreed':'secret'}
function willingMulti(p,other,day){const a=romanceProfiles[p],m=memoryFor(p).feelings;return a[2]>0&&m.hurt<5&&m.security>=(a[2]===2?5:12)&&!coupleIssueRecord(p).active}
function setPair(a,b,mode,consent={},known={}){romanceNetwork().pairs[pairKey(a,b)]={mode,consent,known,day:initSim().day}}
function beginDating(p){const v=initSim(),soc=socialRecord(p);v.romance[p]='dating';v.confessions[p]='accepted';friendshipRecord(p).bond=false;delete soc.aftermath;delete soc.jealousPending;delete soc.jealousKnown;v.couple=v.couple||{};v.couple[p]={since:v.day,seen:{},history:[]};const o=romanceNetwork().offers[p]||(romanceNetwork().offers[p]={});o.status='accepted';romanceNetwork().history.push({day:v.day,p,kind:'start'});writeJournal(p+'와 연인이 되었다.')}
const exVoices={"서이준":[14,2,"이준이 익숙한 걸음 소리에 고개를 들었다가 다시 시선을 내렸다.","…오랜만이네요. 잘 지냈어요?","…전에는 이 시간에 같이 걸었었죠. 이제는 다르지만.","두 분 이야기 마저 해요. 저는 먼저 갈게요.","…그때 끝내기로 한 이유부터 달라져야 하지 않을까요?","…말보다는 시간을 두고 확인하고 싶어요.","…다시 시작해 볼까요. 이번엔 모르는 척하지 말고요.","…미안해요. 그 관계로 돌아가고 싶진 않아요.","저 사람과 어떤 사이인지 제가 다 알 필요는 없죠."],"강도윤":[10,2,"도윤이 반갑게 손을 들다가 잠시 멈췄다.","하하, 잘 지내셨죠? 얼굴 보니 다행이네요.","전에 같이 고르던 메뉴가 아직 있거든요. 문득 생각났어요.","좋은 시간 보내세요. 저는 모카 데리러 가야 해서요.","제가 또 잘해 드리려고만 하는 관계는 아니었으면 해요.","저도 제 마음부터 챙기고 싶어요. 조금 더 지켜봐요.","……이번에는 서로 기대면서 만나 봐요.","하하… 저는 이제 제 일상을 잘 지키고 싶어요.","두 분에게도 좋은 시간이었으면 좋겠어요. 저도 제 몫 챙길게요."],"한시우":[9,2,"시우가 손을 흔들려다 어색하게 머리를 긁적였다.","오, 안녕하세요! …아, 좀 어색하네.","같이 하던 게임 아직 세이브 남아 있더라고요.","오케이. 두 분 즐겜하시고 저는 먼저 갑니다!","재시작한다고 지난 판이 없어지는 건 아니잖아요.","이번엔 진짜 진지하게 생각하고 싶어요.","콜. 이번에는 제대로 같이 해 봐요.","아… 이번에는 친구로 남는 게 좋을 듯해요.","두 분 잘 놀아요. 나도 내 퀘스트 하러 갈게요."],"정태오":[16,3,"태오가 걸음을 늦추고 차분히 인사했다.","안녕하십니까. 오랜만입니다.","함께 보냈던 시간은 소중하게 생각하고 있습니다.","두 분의 시간을 방해하지 않겠습니다.","이전의 문제가 해결됐는지 확인하고 싶습니다.","시간을 두고 판단하는 편이 좋겠습니다.","…다시 교제하고 싶습니다. 서로 솔직히 이야기합시다.","죄송합니다. 이전 관계로 돌아갈 생각은 없습니다.","두 분의 관계는 두 분의 선택이겠지요."],"백지한":[18,3,"지한의 시선이 당신에게서 곁의 사람에게로 옮겨 갔다.","…여기서 또 만날 줄은 몰랐네요.","이 동네가 참 좁죠. 함께 다니던 길이라 그런가 봐요.","오늘은 제가 끼어들 자리가 아닌 것 같네요.","솔직히 아직 마음이 남아 있어요. 그렇다고 똑같이 반복하고 싶지는 않네요.","제가 원하는 것과 당신이 원하는 것을 다시 생각해 볼게요.","…다시 만나 봐요. 이번엔 제 불안 때문에 붙잡아 두려고 하지 않을게요.","마음이 남았다는 것과 다시 만나는 건 별개인 것 같네요.","두 분 사이에 제가 할 말은 없겠죠. …알겠어요."],"임하나":[13,2,"하나가 소매를 만지다가 조심스레 고개를 들었다.","……안녕하세요. 잘 지내셨어요?","그때 함께 골랐던 책은 다 읽었어요.","두 분 좋은 시간 보내세요. 저도 제 볼일이 있어요.","저도 제가 원하는 관계를 다시 생각해 봤어요.","이번에는 제 마음을 숨기지 않고 결정하고 싶어요.","……저도 다시 만나고 싶어요. 이번엔 제 의견도 말할래요.","……저는 지금 제 삶을 더 돌보고 싶어요.","네. 두 분 잘 지내셨으면 좋겠어요."],"차유리":[8,2,"유리가 카메라를 내려놓고 가볍게 손을 들었다.","오, 오랜만! 잘 지냈어요?","같이 봤던 풍경은 여전히 좋았어요. 그림에도 남겨 뒀고.","저는 저쪽 풍경 찍고 올게요. 잘 놀아요.","다시 만나는 것도 좋지만, 서로의 생활을 지킬 수 있어야죠.","좋아요. 일단 편하게 지내면서 알아봐요.","오케이. 다시 만나 보죠. 우리 방식으로.","아, 저는 지금의 관계가 더 편해요.","두 분 사이에 저까지 신경 쓰지 마요. 제 일은 제가 할게요."],"오세린":[12,2,"세린이 잠시 멈춰 부드럽게 미소 지었다.","아아, 오랜만이네요. 평안히 지내셨어요?","예전에 함께 마신 차가 가끔 생각나요.","네. 두 분 편하게 시간 보내세요.","으음, 예전의 문제를 그대로 두고 돌아가지는 않았으면 해요.","천천히 이야기를 나눠 보면 좋겠네요.","네. 다시 만나 볼까요? 각자의 생활도 소중히 하면서요.","아아, 저는 지금의 관계를 유지하고 싶어요.","두 분의 마음은 존중할게요. 저도 제 시간을 보낼게요."],"유지안":[10,2,"지안이 평소처럼 손을 흔들다가 작게 웃었다.","와우, 여기서 만나네요. …잘 지냈어요?","같이 들었던 곡이 가끔 재생되더라고요.","넵! 두 분 잘 놀아요. 저는 연습하러 갈게요.","다시 기대해도 되는지 아직 조금 무서워요.","저도 제 마음을 확실히 알아보고 싶어요.","예쓰… 이번에는 서로 기대하는 걸 솔직하게 말해요.","미안해요. 지금은 다시 시작하고 싶지 않아요.","좋은 시간 보내요. 저도 제 무대 준비해야죠!"],"공재희":[20,3,"재희가 휴대전화를 내려놓고 잠깐 말이 없었다.","아… 오랜만이에요. 잘 지냈어요? 톡 보낼까 하다가 말았어요.","예전 톡은 이제 잘 안 봐요. 가끔 생각나긴 하는데.","아, 웅. 두 분 놀아요. 방송 켜려면 저도 슬슬 가 봐야 돼요.","나 또 혼자 불안해지는 관계는 좀 무서워요.","웅… 잠깐만요. 나 이번엔 답부터 보내고 후회하긴 싫어요.","…웅. 다시 만나고 싶음. 대신 서로 말은 솔직하게 해요.","미안. 나 지금은 다시 만나고 싶지 않음.","아 웅. 잘 지내요. 나도 내 거 하면서 잘 지낼게요."]};
function exRecord(p){return socialRecord(p).exRelationship||null}
function breakupKind(reason){return /비밀|신뢰|양다리/.test(reason)?'trust':/새 관계|다른 사람/.test(reason)?'switch':/합의 철회/.test(reason)?'boundary':/갈등|소통/.test(reason)?'conflict':'ordinary'}
const keepsakeVoices={"서이준":["책갈피","…여기 두고 가도 돼요. 다음에 이어서 읽으면 되니까.","…두고 간 책갈피, 아직 있어요. 돌려드릴게요.","이준이 책 사이에 끼워 둔 책갈피를 조심스럽게 꺼냈다.","익숙한 길인데, 이제는 옆에서 걸음을 맞추던 사람이 없다.","…예전 호칭이 입에 붙었네요. 미안해요."],"강도윤":["작은 머그잔","하하, 다음에 오시면 이 잔으로 커피 내려 드릴게요.","전에 쓰시던 잔이 남아 있네요. 원하시면 챙겨 드릴게요.","도윤은 깨끗이 씻어 말려 둔 잔을 종이에 감쌌다.","커피 향은 그대로인데, 자신을 위해 놓이던 잔은 없다.","하하… 습관처럼 부르게 되네요. 앞으로는 조심할게요."],"한시우":["게임 패드 파우치","오예! 다음 판은 여기서 이어서 하는 거죠?","아, 두고 간 파우치 있어요. 챙겨 갈래요?","시우는 파우치의 지퍼를 닫고 조용히 내밀었다.","익숙한 게임 효과음이 들렸다. 함께 웃던 순간이 문득 떠올랐다.","앗, 예전처럼 불러 버렸네요. 미안."],"정태오":["손수건","두고 가셔도 됩니다. 다음에 돌려드리겠습니다.","두고 가신 손수건을 보관하고 있습니다. 돌려드리고 싶습니다.","태오는 가지런히 접힌 손수건을 건넸다.","익숙한 인도가 이어졌다. 이제는 귀갓길을 묻는 목소리가 없다.","…이전의 호칭을 사용했군요. 실례했습니다."],"백지한":["작은 메모장","좋아요. 다음에 오면 여기서 찾으면 되겠네요.","…두고 간 메모장이 있어요. 가져가실래요?","지한은 메모장을 닫은 채 내밀었다. 더는 페이지를 펼치지 않았다.","함께 걸으며 다음 약속을 정하던 길이다. 오늘의 달력은 비어 있다.","…그 호칭은 이제 쓰면 안 되겠죠."],"임하나":["책","……다음에 같이 읽으면 좋겠어요.","저… 두고 가신 책이 있어요. 잘 보관하고 있었어요.","하나는 책 표지를 한 번 쓸어 보고 두 손으로 건넸다.","전에 함께 고른 책의 표지가 떠올랐다. 오늘은 혼자 걸었다.","……죄송해요. 아직 예전 호칭이 익숙해서요."],"차유리":["스케치 노트","오, 두고 가요! 다음에 그림 이어서 그리죠.","스케치 노트 아직 있어요. 가져갈래요?","유리는 노트 위에 묻은 연필 가루를 털고 내밀었다.","빛이 드는 창가는 그대로다. 그곳에서 나눴던 그림 이야기가 생각났다.","아, 옛날 버릇 나왔네. 호칭 바꿀게요."],"오세린":["차 거름망","으음, 다음에 함께 차를 마실 때 쓰면 되겠네요.","전에 두고 가신 차 거름망이 있답니다. 돌려드릴까요?","세린은 작은 천 주머니에 담긴 거름망을 건넸다.","그날의 차 향이 문득 떠올랐다. 시간은 평소처럼 흐르고 있었다.","아아, 예전 호칭이 나왔네요. 미안해요."],"유지안":["이어폰 케이스","예쓰! 다음에 여기서 노래 더 들어요.","앗, 케이스 두고 갔었죠. 돌려주고 싶어요.","지안은 케이스를 건네고 짧게 웃었다. 음악은 틀지 않았다.","강물은 그날처럼 흘렀다. 함께 듣던 곡이 머릿속에 맴돌았다.","앗… 예전처럼 불렀네요. 미안해요."],"공재희":["인형 키링","웅ㅋㅋ 다음에 올 때 여기서 찾으면 됨!","아, 두고 간 키링 아직 있어요. 돌려줄까요?","재희는 키링을 손에 쥐었다가 살며시 내밀었다.","인형뽑기 기계에 불이 들어왔다. 함께 웃었던 날이 떠올랐다.","아… 예전 호칭 그냥 나왔음. 미안해요."]};
function keepsakeAddress(p){const a=memoryFor(p).address;return {playerToNpc:a.playerToNpc||'',npcToPlayer:a.npcToPlayer||'',playerSpeech:a.playerSpeech||'존댓말',npcSpeech:a.npcSpeech||'존댓말'}}
function saveExKeepsakes(p,e){const v=initSim();stampPhoneSpeech();e.address=keepsakeAddress(p);const a=memoryFor(p).address;delete a.playerToNpc;delete a.npcToPlayer;a.playerSpeech='존댓말';a.npcSpeech='존댓말';delete a.playerCallChanges;e.places=dateHistory(p).filter(x=>x.day>=e.since&&x.day<=e.day).map(x=>({day:x.day,venue:x.venue}));e.keepsakes=[];for(const x of souvenirList().filter(x=>x.person===p&&x.day<=e.day&&!x.disposed)){x.exMarked=true;e.keepsakes.push({name:x.name,day:x.day,venue:x.venue})}e.gifts=[];if(v.birthdayGifts?.[p])e.gifts.push({id:'birthday',name:v.birthdayGifts[p],status:'keep'});if(p==='공재희'&&v.jaeheeBear)e.gifts.push({id:'bear',name:'흰색 곰인형',status:'keep'});e.homeBelonging=coupleRecord(p).homeBelonging?{...coupleRecord(p).homeBelonging}:null;e.reminders=[];}
function keepsakeHomeOffer(ev,p){if(!vIsDating(p)||ev.homeScene!==3)return false;const r=coupleRecord(p),a=keepsakeVoices[p];if(!ev.belongingOffer){if(r.homeBelonging)return false;ev.belongingOffer={};save()}const o=ev.belongingOffer;if(o.answer){add(state.name,o.answer==='leave'?a[0]+'을(를) 다음에 쓰려고 두고 간다':'오늘 가져온 물건은 모두 챙긴다',true);if(o.answer==='leave')add(p,a[1]);return false}add('이야기','돌아가기 전, 가져왔던 '+a[0]+'을(를) 챙길지 생각했다.');for(const [label,k] of [[a[0]+'을(를) 다음에 쓰려고 두고 간다','leave'],['오늘 가져온 물건은 모두 챙긴다','take']])choiceButton(label,()=>{if(o.answer)return;o.answer=k;if(k==='leave'){r.homeBelonging={name:a[0],day:initSim().day,status:'left'};remember(p,'belonging:'+initSim().day,a[0]+'을 두고 감')}save();renderChoiceEvent();renderSim()});return true}
function exMemoryPlace(venue){return ({'오락실':'arcade','수영장':'pool','연화천 산책':'river','고양이 산책':'park','사진 산책':'park','홈데이트':'home','카페':'cafe','카페 데이트':'cafe'})[venue]||null}
function exPlaceCandidate(place,day){const v=initSim();return people.find(p=>{const e=exRecord(p);return v.romance[p]==='ended'&&e&&day>e.day+1&&e.places?.some(x=>exMemoryPlace(x.venue)===place)&&!e.reminders?.some(x=>x.place===place)})||null}
function renderExMemory(ev){const v=initSim(),p=ev.exMemory.person,e=exRecord(p),a=keepsakeVoices[p];$('progress').textContent='남겨진 추억';add('이야기',a[4]);if(ev.exMemory.answer){add('이야기',ev.exMemory.answer);choiceButton('일정 계속하기',finishEvent);return}for(const [label,reply] of [['그날의 추억을 잠시 떠올린다','좋았던 시간은 있었고, 오늘의 나는 그 이후를 살아가고 있다.'],['지금의 일상에 집중한다','잠시 멈췄던 걸음을 다시 옮겼다.']])choiceButton(label,()=>{if(ev.exMemory.answer)return;ev.exMemory.answer=reply;e.reminders=e.reminders||[];e.reminders.push({day:v.day,place:ev.place,label});remember(p,'ex:place:'+ev.place,label);save();renderChoiceEvent()})}
function exKeepsakeControls(p,root){const v=initSim(),e=exRecord(p);if(v.romance[p]!=='ended'||!e||v.running||v.activeEvent||v.finished)return;const b=e.homeBelonging;if(b?.status==='left'&&v.day>=e.day+2){const btn=document.createElement('button');btn.className='secondary';btn.textContent='두고 온 '+b.name+' 돌려받기';btn.onclick=()=>{if(v.running||v.activeEvent||b.status!=='left')return;v.activeEvent={place:'home',person:p,day:v.day,description:'두고 온 물건을 돌려받기로 했다.',exBelonging:{name:b.name}};save();renderChoiceEvent()};root.append(btn)}if(aftermathRecord(p)?.status!=='friend')return;
 const pending=!e.friendAddressMode;
 const canRenegotiate=e.friendAddressMode==='first'&&!memoryFor(p).address.offerDay;
 if(!pending&&!canRenegotiate)return;
 const btn=document.createElement('button');btn.className='secondary';
 btn.textContent=pending?'친구로서 말투와 호칭 정하기':'친구로서 말 놓기 이야기하기';
 btn.onclick=()=>{
  if(v.running||v.activeEvent||v.finished||v.romance[p]!=='ended')return;
  v.activeEvent={place:'home',person:p,day:v.day,description:'친구로서 어떻게 대화할지 이야기를 나눴다.'};
  if(pending)v.activeEvent.exAddress={};else v.activeEvent.speechOffer=true;
  save();renderChoiceEvent();
 };
 root.append(btn);
}
function renderExBelonging(ev){const v=initSim(),p=ev.person,e=exRecord(p),a=keepsakeVoices[p],o=ev.exBelonging;$('progress').textContent='돌려받는 물건';add(p,a[2]);add('이야기',a[3]);if(o.answer){add(state.name,o.answer,true);choiceButton('일정 계속하기',finishEvent);return}for(const label of ['고마워요. 가져갈게요.','문 앞에 놓아 주세요. 나중에 챙길게요.'])choiceButton(label,()=>{if(o.answer)return;o.answer=label;e.homeBelonging.status='returned';remember(p,'ex:return:'+v.day,o.name);writeJournal(p+' · '+o.name+' 반환');save();renderChoiceEvent();renderSim()})}
const exFriendAddressChoices=[['처음처럼 대한다','first'],['애칭만 취소한다','nicknameOnly']];
function chooseExFriendAddress(p,mode){
 const e=exRecord(p),a=memoryFor(p).address;
 stampPhoneSpeech();
 delete a.playerToNpc;delete a.npcToPlayer;delete a.playerCallChanges;
 delete a.offerDay;delete a.nicknameOffered;
 if(mode==='nicknameOnly'){
  a.playerSpeech=e.address?.playerSpeech||'존댓말';
  a.npcSpeech=e.address?.npcSpeech||'존댓말';
 }else{
  delete a.playerSpeech;delete a.npcSpeech;
 }
 e.friendAddressMode=mode;
 e.addressRecall=initSim().day;
}
function exFriendAddressButtons(ev){
 const v=initSim(),p=ev.person;
 for(const [label,mode] of exFriendAddressChoices)choiceButton(label,()=>{
  if(v.activeEvent!==ev||exRecord(p).friendAddressMode)return;
  chooseExFriendAddress(p,mode);save();renderChoiceEvent();renderSim();
 });
}
function renderExAddress(ev){
 const p=ev.person,e=exRecord(p);
 $('progress').textContent='친구로서의 말투와 호칭';
 if(e.friendAddressMode||ev.exAddress.answer){
  add(state.name,ev.exAddress.answer||exFriendAddressChoices.find(([,mode])=>mode===e.friendAddressMode)?.[0],true);
  choiceButton('일정 계속하기',finishEvent);return;
 }
 add('이야기','친구로 지내면서 서로 어떻게 말하고 부를지 정하기로 했다.');
 exFriendAddressButtons(ev);
}
function exKeepsakePanel(root){const v=initSim();for(const p of people){const e=exRecord(p);if(!e)continue;const d=document.createElement('details'),h=document.createElement('summary');h.textContent=p+' · 지난 관계의 기록';d.append(h);const note=document.createElement('p');note.textContent=calendarDate(e.since).label+' ~ '+calendarDate(e.day).label+' · '+e.reason;d.append(note);if(e.address?.npcToPlayer||e.address?.playerToNpc){const t=document.createElement('p');t.textContent='예전 호칭: '+[e.address.playerToNpc,e.address.npcToPlayer].filter(Boolean).join(' / ');d.append(t)}for(const g of e.gifts||[]){const t=document.createElement('p');t.textContent=g.name+' · '+(g.status==='store'?'따로 보관':g.status==='discard'?'정리함':'간직 중');d.append(t);if(g.status!=='discard'){const sel=document.createElement('select');for(const [k,l] of [['keep','간직하기'],['store','따로 보관하기'],['discard','정리하기']]){const o=document.createElement('option');o.value=k;o.textContent=l;sel.append(o)}sel.value=g.status;sel.onchange=()=>{if(sel.value==='discard'&&!confirm(g.name+'을(를) 정리할까요?')){sel.value=g.status;return}g.status=sel.value;save();renderSim()};d.append(sel)}}if(e.homeBelonging){const t=document.createElement('p');t.textContent=e.homeBelonging.name+' · '+(e.homeBelonging.status==='returned'?'돌려받음':'상대의 집에 남아 있음');d.append(t)}for(const x of e.places||[]){const t=document.createElement('small');t.textContent=calendarDate(x.day).label+' · '+x.venue;d.append(t,document.createElement('br'))}root.append(d)}}

function saveExRelationship(p,reason){const v=initSim(),soc=socialRecord(p),prev=exRecord(p),kind=breakupKind(reason),a=exVoices[p],old=coupleRecord(p);soc.exRelationship={day:v.day,since:old.since,reason,kind,readyDay:v.day+a[0]+(kind==='trust'?21:kind==='switch'?7:0),remaining:Math.min(12,4+Math.floor(flirtRecord(p).interest/4)),repair:0,lastTalk:0,history:[],past:[...(prev?.past||[]),...(prev?[{day:prev.day,reason:prev.reason,history:prev.history}]:[])],previousCouple:JSON.parse(JSON.stringify(old)),knownNew:null,status:'apart'};saveExKeepsakes(p,soc.exRelationship);}
function exCanTalk(p,day){const e=exRecord(p),a=aftermathRecord(p);return !!(e&&initSim().romance[p]==='ended'&&day>=e.readyDay&&a?.status==='friend'&&(!e.lastTalk||day-e.lastTalk>=5))}
function exRequired(p,e){return exVoices[p][1]+(e.kind==='trust'?3:e.kind==='switch'?1:0)}
function exCanReunite(p,day){const e=exRecord(p);return !!(exCanTalk(p,day)&&!lovers().length&&e.repair>=exRequired(p,e)&&e.remaining>=2&&memoryFor(p).feelings.hurt<5)}

const EX_AFTER_VOICES={
"서이준":{place:"연화빌라 복도",first:"…책을 빌려주려고 꺼냈다가 연락처를 눌렀어요. 안 보내려다가요. 아직 습관이 안 고쳐지네요.",meet:"문 앞에 놓인 택배를 가지러 나오자 이준이 계단 아래에서 올라왔다. 서로 길을 비켜 주려다 동시에 멈췄다.",confess:"…아무렇지도 않으려고 했는데, 집에 돌아올 때마다 옆집 불부터 보게 돼요. 그런 내가 좀 싫었어요.",stay:"이번에는 혼자 답을 정하지 않을게요. 당신 말부터 들을게요.",part:"…네. 더는 기다리지 않을게요. 오늘은 그냥 인사하고 갈게요.",later:"…다시 사귀자는 말을 지금 해도 될지 모르겠어요. 그래도 나는 아직 당신이 좋아요."},
"강도윤":{place:"카페 앞 골목",first:"오늘 잔을 두 개 꺼냈다가 하나를 다시 넣었어요. 괜히 이런 문자 보내서 미안해요. …잘 지내고 있어요?",meet:"가게 문을 닫던 도윤이 당신을 발견했다. 평소라면 웃으며 인사했을 사람이 손잡이를 놓고 한참 망설였다.",confess:"잘 지내야 한다고 생각했어요. 내가 먼저 잘 지내야 당신도 편할 테니까. 근데 아직은 별로 안 괜찮아요. …보고 싶었어요.",stay:"그때 왜 그렇게 서운했는지 저도 말해 볼게요. 이번엔 나도 괜찮은 척 안 할래요.",part:"…네. 답답하게 해서 미안해요. 다시 마주치면 인사는 할게요.",later:"아직도 자꾸 같이 저녁 먹을 시간을 비워 놔요. 돌아올 생각이 없다면 기다리지 않을게요. 하지만 마음이 남아 있다면… 나도 남아 있어요."},
"한시우":{place:"오락실 앞 자판기",first:"우리 같이 하던 게임 새 업데이트 떴어요. …아, 그런 거 보내면 안 되지. 미안해요. 그냥 제일 먼저 얘기하고 싶었어요.",meet:"자판기 앞에서 시우가 동전을 넣었다가 꺼냈다. 눈이 마주치자 평소처럼 웃으려다가 입술만 달싹였다.",confess:"나 요즘 웃긴 거 봐도 아무한테나 보내기 싫어요. 제일 먼저 생각나는 사람이 아직 당신이거든요. …나 좀 한심해요?",stay:"그럼 이번엔 진짜 안 웃기고 듣기만 할게요. 어디서부터 꼬였는지 같이 얘기해 봐요.",part:"…알겠어요. 안 따라갈게요. 좀 울고 나면 나아지겠죠.",later:"한 번만 더 나랑 만나 주면 안 돼요? 바로 대답 안 해도 돼요. 그냥… 나 아직 너무 좋아하거든요."},
"정태오":{place:"연화천 산책로",first:"안부를 묻는 것이 부담이 될까 망설였습니다. 답은 주지 않으셔도 됩니다. …무사히 지내고 계신지 궁금했습니다.",meet:"퇴근 뒤 산책하던 태오와 강변에서 마주쳤다. 태오는 걸음을 멈췄지만 당신 쪽으로 다가오지는 않았다.",confess:"결정은 존중했습니다. 그런데 그 뒤로도 하루에 몇 번씩 안부를 묻고 싶었습니다. 제가 아직 마음을 놓지 못한 모양입니다.",stay:"감사합니다. 그날 하지 못한 말을 차근차근 나누고 싶습니다.",part:"알겠습니다. 앞으로 제 마음으로 불편하게 해 드리지 않겠습니다.",later:"다시 시작할 가능성이 있는지 묻고 싶습니다. 물론 거절하신다면 더 권하지 않겠습니다."},
"백지한":{place:"공원 입구",first:"오늘도 습관처럼 다음 주 일정을 확인했어요. 비어 있는 날이 많네요. …이런 얘길 왜 보내는지 저도 모르겠어요.",meet:"가로등 아래에서 지한이 당신을 발견했다. 곧장 다가오려던 걸음이 멎었다. 그는 잠시 넥타이를 만지작거렸다.",confess:"솔직히 아직도 당신이 다른 사람과 웃는 걸 상상하면 속이 뒤집혀요. 그런데 그건 내 욕심이고, 당신 잘못이 아니죠. …그래도 보고 싶습니다.",stay:"제가 원하는 답을 강요하지 않을게요. 다만 이번에는 제 마음도 숨기고 싶지 않아요.",part:"…알겠습니다. 더 붙잡지는 않겠어요. 지금은 그 말도 꽤 어렵네요.",later:"다시 제 곁에 와 달라고 말하고 싶어요. 대신 이전처럼 제 뜻대로 할 생각은 없습니다. 선택은 당신이 해요."},
"임하나":{place:"편의점 옆 골목",first:"오늘 아르바이트 끝나고 좋아하던 과자를 봤어요. 저도 모르게 두 개를 집었다가… 하나만 계산했어요. 잘 지내세요?",meet:"퇴근한 하나가 편의점에서 나왔다. 당신을 보더니 봉투를 꼭 쥐고 눈을 내리깔았다가, 다시 고개를 들었다.",confess:"괜찮다고 하면 진짜 괜찮아질 줄 알았어요. …아직 안 괜찮아요. 저도 너무 보고 싶었어요. 이런 말 하면 곤란하죠?",stay:"제가 하고 싶은 말도 조금씩 해 볼게요. 혼자 참고 있다가 또 잃고 싶지 않아요.",part:"…네. 더 연락 안 할게요. 저 때문에 미안해하지는 마세요.",later:"저, 한 번만 더 기회 달라고 해도 될까요? 이번에는 제 마음도 말할게요. 나 아직 좋아해요."},
"차유리":{place:"공원 화단 앞",first:"스케치북 정리하다가 같이 갔던 전시 티켓 나왔어요. 버리긴 싫어서 그냥 넣어 뒀어요. …이 말 왜 보내냐, 나도 모르겠네.",meet:"화단 앞에 앉아 있던 유리가 고개를 들었다. 스케치북을 덮으려다 그만두고, 당신이 다가오는 걸 지켜봤다.",confess:"나 원래 이런 말 안 하는데. 헤어지고 나서야 당신한테 보여 주려고 그렸던 게 많다는 걸 알았어요. 진짜 짜증 나. 아직 좋아해서.",stay:"이번엔 못 들은 척 안 할게요. 나도 서운했던 거 다 말할 테니까.",part:"알았어요. …그래도 함께한 시간은 지우고 싶지 않네요.",later:"나 아직 마음 남아 있어요. 우리 다시 만날 수 있을까요? 아니면 그냥 내가 여기서 끝낼게요."},
"오세린":{place:"동물병원 근처 찻집",first:"오랜만에 좋아하시던 차를 마셨어요. …이런 이야기를 보낼 사이가 아니라는 걸 알면서도 생각이 났네요. 잘 지내시지요?",meet:"찻집 앞에서 세린과 마주쳤다. 세린은 잠깐 시선을 내렸다가 조심스럽게 웃었다. 인사하고 지나가기에는 걸음이 느렸다.",confess:"어른스럽게 보내 드리면 마음도 따라서 정리될 거라 여겼어요. 생각보다 그렇지 않더라고요. 아직 많이 그리워요.",stay:"그래요. 저도 이번에는 편안한 말만 고르지 않을게요.",part:"알겠어요. 내 마음은 내가 잘 돌볼게요. 고마웠어요.",later:"혹시 지금보다 조금 더 가까운 관계를 다시 생각해 볼 수 있을까요? 서두르실 필요는 없어요."},
"유지안":{place:"연화천 벤치",first:"노래 들었는데 같이 걷던 길 생각났어요. ㅋㅋ 나 이런 문자 보내면 안 되나? …아직 잘 모르겠어요.",meet:"운동을 마치고 돌아오던 지안이 벤치 옆에 멈췄다. 이어폰 한쪽을 빼고, 해맑게 인사하려던 얼굴이 금세 시무룩해졌다.",confess:"나 헤어진 뒤에도 자꾸 같이 갈 데를 찾아요. 멍청하죠? 근데 같이 가고 싶단 생각이 안 없어져요. 나 아직 좋아하나 봐.",stay:"그럼 오늘은 도망 안 갈게요. 나도 솔직하게 말할래요.",part:"…응. 안 붙잡을게요. 그래도 오늘은 좀 울래.",later:"나 아직 너랑 하고 싶은 게 엄청 많아요. 다시 만나자고 하면… 너무 늦었을까요?"},
"공재희":{place:"오락실 앞 거리",first:"아니 근데 나 왜 자꾸 톡 보내려다가 멈춤ㅋㅋ …웃기려고 보낸 거 아님. 그냥 오늘 너무 보고 싶었어요.",meet:"오락실에서 나온 재희가 당신을 보고 발걸음을 멈췄다. 인형이 든 봉투를 뒤로 숨기다가 그대로 바닥에 내려놓았다.",confess:"내가 그때 자존심 부렸던 거 알죠? 나 안 보겠다고 해 놓고 진짜 안 보니까… 너무 싫어요. 나 아직 좋아한다고요.",stay:"응. 오늘은 나 안 도망가요. 화난 거 있으면 다 얘기해 줘요.",part:"…알았어요. 나 진짜 싫지만 안 쫓아갈게요. 지금은 그냥 울래.",later:"나 다시 만나고 싶어요. 농담 아니고 진짜로. …나 좀 봐 주면 안 돼요?"}
};
function exAfterEligible(p){const v=initSim(),e=exRecord(p);return !!(e&&v.romance[p]==='ended'&&e.initiator!=='npc'&&e.kind!=='trust'&&!v.finished&&v.day<365)}
function exAfterState(p){const e=exRecord(p);if(!e)return null;return e.after||(e.after={notice:0,reply:null,scene:0,decision:null,last:0})}
function exAfterNight(day){
 for(const p of people){
  if(!exAfterEligible(p))continue;
  const e=exRecord(p),a=exAfterState(p);
  if(!a.notice&&day>=e.day+2){
   a.notice=day;const t=phoneData().threads[p]||(phoneData().threads[p]=[]);
   t.push({day,exAfterText:true,npcLine:EX_AFTER_VOICES[p].first,reply:0});
   remember(p,'ex:unsent:'+day,'이별 후 먼저 온 안부');
  }
 }
}
function exAfterGate(){
 const v=initSim();
 if(v.day>=365||v.activeEvent||v.running||v.finished||dateBook()[v.day]?.trip||v.day===299||v.day===300)return false;
 for(const p of people){
  if(!exAfterEligible(p))continue;
  const e=exRecord(p),a=exAfterState(p);
  if(!a.notice||a.reply==='no'||a.decision==='stop'||a.decision==='reunited')continue;
  let chapter=0;
  if(a.scene===0&&v.day>=e.day+(a.reply?5:8))chapter=1;
  else if(a.scene===1&&a.decision==='talk'&&v.day>=a.last+7)chapter=2;
  if(!chapter)continue;
  a.scene=chapter;a.last=v.day;
  v.activeEvent={place:chapter===1?'park':'river',person:p,day:v.day,description:EX_AFTER_VOICES[p].meet,exAfter:{chapter}};
  save();renderChoiceEvent();return true;
 }
 return false;
}
function renderExAfter(ev){
 const v=initSim(),p=ev.person,e=exRecord(p),a=exAfterState(p),o=ev.exAfter,voice=EX_AFTER_VOICES[p],first=o.chapter===1;
 $('progress').textContent=first?'끝내지 못한 이야기 · '+p:'다시 묻는 마음 · '+p;
 add('이야기',first?voice.meet:'오랜만에 마주 앉자, '+p+'이(가) 먼저 말을 꺼내기까지 긴 시간이 걸렸다.');
 const face=argumentPortraits[p];
 add(p,first?voice.confess:voice.later,false,false,first?face.truth:face.early);
 if(o.answer){
  add(state.name,o.answer.label,true);
  add(p,o.answer.reply,false,false,o.answer.reply===voice.part?face.unresolved:face.listen);
  choiceButton('일정 계속하기',finishEvent);return;
 }
 const choices=first?[
  ['나도 아직 생각나. 하지만 먼저 헤어지자고 했던 이유는 남아 있어.','talk',voice.stay],
  ['이야기는 들을게. 지금 당장 답은 못 하겠어.','wait',voice.stay],
  ['미안해. 다시 만날 생각은 없어.','stop',voice.part]
 ]:[
  ['내 마음도 아직 남아 있어. 시간을 두고 다시 이야기하자.','talk',voice.stay],
  ['나는 지금은 친구로 지내고 싶어.','wait',voice.part],
  ['여기서 끝내는 게 맞을 것 같아.','stop',voice.part]
 ];
 for(const [label,k,reply] of choices)choiceButton(label,()=>{
  if(o.answer)return;
  o.answer={label,reply};a.decision=k;a.last=v.day;
  if(k==='talk'){e.remaining=Math.min(12,e.remaining+1);feel(p,{hurt:-1});}
  if(k==='stop'){a.reply='no';e.remaining=Math.max(0,e.remaining-1);}
  remember(p,'ex:after:'+o.chapter+':'+v.day,label);
  writeJournal(p+' · 이별 뒤 다시 마주한 마음');
  save();renderChoiceEvent();renderSim();
 });
}
function renderExAfterPhone(p,m,group,bubble){
 const a=exAfterState(p),v=initSim(),voice=EX_AFTER_VOICES[p];
 bubble(p,m.npcLine,false,true);
 if(m.reply){
  if(m.afterLabel)bubble(state.name,m.afterLabel,true,true);
  if(m.afterReply)bubble(p,m.afterReply,false,true);
  return;
 }
 const opts=[
  ['나도 아직 생각나. 잘 지내는지 궁금했어.','warm','…답해 줘서 고마워요. 당장 무슨 말을 해 달라는 건 아니에요.'],
  ['연락은 받았어. 아직은 좀 복잡해.','quiet','…알아요. 당장 답을 바라지는 않을게요.'],
  ['이제는 연락하지 않았으면 좋겠어.','no','…알겠어요. 더 연락하지 않을게요.']
 ];
 for(const [label,k,reply] of opts){
  const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=label;
  button.onclick=()=>{
   if(m.reply)return;
   m.reply=k==='no'?3:k==='warm'?1:2;m.afterLabel=label;
   m.afterReply=k==='no'?voice.part:reply;
   a.reply=k;a.last=v.day;
   if(k==='warm')exRecord(p).remaining=Math.min(12,exRecord(p).remaining+1);
   if(k==='no')a.decision='stop';
   remember(p,'ex:textreply:'+v.day,label);save();phoneBadge();renderPhone();renderSim();
  };group.append(button);
 }
}

function exNight(day){exAfterNight(day);for(const p of people){const e=exRecord(p);if(!e||initSim().romance[p]!=='ended'||day<=e.day)continue;if((day-e.day)%7===0)e.remaining=Math.max(0,e.remaining-(e.repair?0:1))}}
function exControls(p,root){const v=initSim(),e=exRecord(p);if(!e||v.romance[p]!=='ended')return;const t=document.createElement('p');t.className='muted-note';t.textContent='이전 관계 · '+(e.kind==='trust'?'신뢰의 상처':e.kind==='switch'?'다른 연인을 선택한 이별':e.kind==='boundary'?'관계 방식의 차이':e.kind==='conflict'?'갈등으로 인한 이별':'헤어진 연인');root.append(t);if(!exCanTalk(p,v.day)||v.running||v.activeEvent||v.finished)return;const b=document.createElement('button');b.className='secondary';b.textContent=exCanReunite(p,v.day)?'다시 만날 수 있을지 이야기하기':'지난 관계를 돌아보며 이야기하기';b.onclick=()=>{if(v.running||v.activeEvent||!exCanTalk(p,v.day))return;v.activeEvent={place:'home',person:p,day:v.day,description:'예전과는 다른 관계에서 다시 이야기를 나누기로 했다.',exTalk:{ready:exCanReunite(p,v.day)}};save();renderChoiceEvent()};root.append(b)}
function renderExTalk(ev){const v=initSim(),p=ev.person,e=exRecord(p),a=exVoices[p],o=ev.exTalk;$('progress').textContent='다시 마주한 마음';const face=argumentPortraits[p];add(p,e.kind==='trust'?romanceProfiles[p][7]:a[6],false,false,e.kind==='trust'?face.truth:face.early);if(o.answer){add(state.name,o.answer.label,true);add(p,o.answer.reply,false,false,o.answer.reunited?confessionPortraits[p].accepted:o.answer.reply===a[7]?face.listen:face.unresolved);choiceButton('일정 계속하기',finishEvent);return}const opts=[['지난 관계에서 내가 놓친 부분을 이야기하고 상대의 말을 듣는다','listen'],['다시 연인이 되고 싶다고 말한다','ask'],['친구로 남고 각자의 삶을 응원한다','friend']];for(const [label,k] of opts)choiceButton(label,()=>{if(o.answer)return;let reply;if(k==='listen'){e.repair++;e.remaining=Math.min(12,e.remaining+1);feel(p,{hurt:-2,security:2});reply=a[7]}else if(k==='ask'&&o.ready&&exCanReunite(p,v.day)){reply=a[8];e.status='reunited';e.reunitedDay=v.day;beginDating(p);if(e.kind==='trust'){const pressure=relationshipPressure(p);pressure.distrust=Math.max(5,pressure.distrust);pressure.obsession=Math.max(5,pressure.obsession);if(p===JIHAN){const z=jihanBond();if(!z.scar)jihanScar(e.day);z.mutedUntil=0;}}coupleRecord(p).previous=e.previousCouple;remember(p,'ex:reunited:'+v.day,reply)}else if(k==='ask'){reply=a[9]}else{e.remaining=Math.max(0,e.remaining-2);reply=a[10]}e.lastTalk=v.day;e.history.push({day:v.day,kind:k,label,reply});o.answer={label,reply,reunited:e.status==='reunited'};writeJournal(p+' · '+(o.answer.reunited?'다시 시작한 연애':'지난 관계에 대한 대화'));save();renderChoiceEvent();renderSim()})}

