function exNewTriangleGate(){
 const v=initSim(),day=v.day,active=lovers();
 if(day<8||day>=365||v.finished||v.activeEvent||v.running||dateBook()[day]?.trip||[299,300].includes(day)||active.length!==1)return false;
 const p=active[0],started=coupleRecord(p)?.since||day;
 if(day-started<3)return false;
 for(const q of people){
  const e=exRecord(q);
  if(q===p||!e||v.romance[q]!=='ended'||!e.day||e.day>=started||e.kind==='trust'||e.initiator==='npc')continue;
  if(e.newTriangleWith?.includes(p)||e.remaining<2||exAfterState(q)?.decision==='stop'||exAfterState(q)?.reply==='no')continue;
  if(day<Math.max(started+3,e.day+5))continue;
  const o={lover:p,other:q,place:'river',day,slot:2,level:2,fromDate:false,exNewScene:true};
  e.newTriangleWith=(e.newTriangleWith||[]).concat(p);
  v.activeEvent={place:'river',person:p,day,description:'연화천에서 연인과 나란히 걷던 중 익숙한 사람이 앞에서 멈춰 섰다.',triangle:o};
  save();renderChoiceEvent();return true;
 }
 return false;
}

