function multiVoice(p){return multiVoices[p]||[trianglePartner[p][0],trianglePartner[p][3],trianglePartner[p][4],trianglePartner[p][5],trianglePartner[p][4],coupleConflictVoices[p].lines[2],coupleConflictVoices[p].lines[4],romanceProfiles[p][8]]}
function multiState(a,b){const x=pairState(a,b);if(!x)return null;if(!x.dynamic)x.dynamic={affinity:0,dates:0,history:[],individual:{}};for(const p of [a,b])if(!x.dynamic.individual[p])x.dynamic.individual[p]={jealous:0,missed:0,attention:0,need:false,lastDiscussion:0};return x.dynamic}
function clampMulti(x){return Math.max(0,Math.min(12,x))}
function multiChoiceEffects(d,a,choice,sensitivity){const favor=a.includes(choice)?choice:null;for(const p of a){const z=d.individual[p];if(favor===p){z.attention++;z.missed=0;z.jealous=clampMulti(z.jealous-2)}else if(favor){z.missed++;z.jealous=clampMulti(z.jealous+(z.missed>=2?sensitivity[p]+1:sensitivity[p]));}else if(choice==='shared'){z.missed=0;z.jealous=clampMulti(z.jealous-2)}else if(choice==='space'){z.jealous=clampMulti(z.jealous-1)}if(z.jealous>=5)z.need=true;}d.affinity=Math.max(-8,Math.min(12,d.affinity+(choice==='shared'?2:choice==='space'?1:favor&&a.some(p=>p!==favor&&d.individual[p].missed>=2)?-1:0)));return d}
function multiSensitivity(p){return p==='유지안'||p==='한시우'?2:p==='오세린'||p==='차유리'?1:2}
function multiTension(p,q){const d=multiState(p,q);return d?d.individual[p].jealous:0}
function multiKnownDate(p,q,day){if(!bothConsented(p,q))return;const d=multiState(p,q),key='known:'+p+':'+q+':'+day;if(d.history.some(x=>x.key===key))return;const z=d.individual[p];z.missed++;z.jealous=clampMulti(z.jealous+multiSensitivity(p));if(z.jealous>=5)z.need=true;d.history.push({key,day,kind:'knownDate',person:p,other:q});}
