const friendshipVoices={"서이준":["서점","서가에서 서로 골라 준 책을 펼쳐 보았다.","…이 책은 좀 궁금했어요. 읽고 나면 이야기해요.","…요즘 일은 괜찮아요? 그냥 들어 줄 수는 있어요.","…친구라고 해서 매일 연락해야 하는 건 아니잖아요. 그래도 필요할 때 연락해요.","…새해에도 가끔 게임이나 같이 해요. 편하게."],"강도윤":["연화천 산책","모카가 두 사람 사이를 오가며 꼬리를 흔들었다.","하하, 오늘은 모카가 산책 코스를 정하는 날인가 봐요.","요즘 너무 혼자 해결하려고 하는 건 아니에요? 저한테도 이야기해 봐요.","하하, 저도 가끔은 친구한테 기대도 되겠죠?","내년에도 커피 한 잔 하러 와요. 제가 손님으로 놀러 가도 되고요."],"한시우":["오락실","서로 다른 게임에 도전하고 점수를 비교했다.","오예! 오늘은 진 사람이 음료 사기! 무리한 내기는 금지.","아, 그건 좀 힘들었겠다. 일단 얘기해 봐요. 내가 듣고 있을게요.","우리 친구잖아요. 한동안 각자 바빠도 접속하면 같이 놀면 되죠.","내년에도 파티원 모집할 때 나 빼면 안 됨!"],"정태오":["수영장","수영을 마치고 휴게실에서 물을 마셨다.","오늘은 기록보다 몸 상태를 우선하는 편이 좋겠습니다.","필요하다면 함께 방법을 찾아보겠습니다. 먼저 이야기를 듣겠습니다.","친구 사이에도 각자의 시간이 필요합니다. 부담 갖지 마십시오.","앞으로도 평안하시길 바랍니다. 다음 봉사에도 함께하실 수 있으면 좋겠군요."],"백지한":["건축 산책","골목을 걸으며 눈에 들어오는 건물 이야기를 나눴다.","저 창문 위치 좀 봐요. 살다 보면 저런 게 은근히 중요하거든요.","제가 답을 정해 줄 수는 없지만, 같이 생각해 볼 수는 있죠.","친구한테도 무리하게 시간을 요구하면 안 되겠죠. 편할 때 연락해요.","내년에는 재미있는 건물 하나 같이 보러 가죠. 친구로서 약속."],"임하나":["서점","서로 읽고 싶은 책을 고르고 감상을 이야기했다.","……이 책 읽으면 나중에 이야기해 주실래요? 저도 궁금해요.","저도 잘 들어 드릴 수는 있어요. 천천히 말해 주세요.","……저도 가끔 먼저 연락해도 되죠? 친구니까요.","내년에도 서로 하고 싶은 일을 응원하면서 지내요."],"차유리":["소품 공방","각자 고른 재료로 작은 소품을 만들었다.","오, 그 색 좋다! 완전 다른 취향인데 같이 만들면 재밌네요.","아, 그건 속상할 만하네. 해결책 필요한 거예요, 아니면 그냥 들어 줄까요?","우리 각자 잘 살다가 재밌는 거 생기면 공유해요. 그게 편하잖아.","내년에도 작업하다 심심하면 불러요. 맛있는 거 먹으러 가자!"],"오세린":["디저트 카페","차와 작은 디저트를 고르고 각자의 근황을 이야기했다.","으음, 오늘은 여유 있게 먹고 가면 좋겠네요.","아아, 마음이 복잡하셨겠어요. 지금 가장 필요한 게 무엇인지 생각해 볼까요?","서로의 생활을 존중하는 친구가 있다는 건 참 좋은 일이네요.","새해에도 가끔 차를 마시며 안부를 나눠요."],"유지안":["연화천 산책","이어폰으로 각자 고른 노래를 번갈아 들으며 걸었다.","와우, 이 노래 좋다! 다음 러닝 플레이리스트에 넣어야겠어요.","예쓰… 아니, 오늘은 그냥 들어 줄게요. 힘든 날도 있잖아요.","친구니까 꼭 똑같은 속도로 뛸 필요는 없죠. 각자 페이스로!","내년에도 같이 뛰어요! 아니면 걷기만 해도 좋고요."],"공재희":["오락실","인형뽑기 기계 앞에서 각자 마음에 드는 인형을 골랐다.","헐ㅋㅋ 저거 귀엽다. 오늘은 서로 뽑아 주기 어때요?","아 뭐야, 그런 일 있었음? 말해 봐요. 나 오늘 방송 끝났어요.","웅. 답장 늦어도 괜찮음. 친구도 각자 할 일 있잖아요.","내년에도 인형뽑기 가자ㅋㅋ 서로 바쁠 땐 나중에 만나면 되지."]};
const friendCrushVoices={"서이준":["…그 사람이 아니라 저한테 먼저 이야기해 주면 좋겠다고 생각했어요. 이상하네요.","…좋아하게 된 것 같아요. 친구로 지내는 시간이 제게는 생각보다 컸어요.","…알겠어요. 조금 정리할 시간이 필요해요.","…다시 편하게 이야기할 수 있으면 좋겠어요.","그 사람이 좋아한다는 건 알겠어요. …어떻게 하고 싶어요?"],"강도윤":["하하, 제가 그 사람이었으면 그렇게 오래 기다리게 하지 않았을 텐데.","친구라서 챙기고 싶은 줄 알았는데, 그게 전부는 아니었나 봐요.","네. 마음을 받아 달라고 고집하지 않을게요.","하하, 다시 커피 한 잔 할 수 있으면 좋겠네요.","그분이 당신을 챙기는 걸 보면 저도 모르게 비교하게 되네요."],"한시우":["아, 이거 왜 내가 더 신경 쓰이지? 친구 상담인데.","저요, 친구 모드인 줄 알았는데 아니었나 봐요. 좋아해요.","오케이. 좀 민망하긴 한데 답은 존중할게요.","콜! 예전처럼 게임 한 판부터 할까요?","앗, 그 친구한테 마음 있다는 말 들으니까 괜히 경쟁전 된 기분인데요."],"정태오":["…제가 당사자였다면 어땠을지 생각했습니다. 개인적인 감정이 섞였군요.","친구로서의 마음만은 아니라는 것을 알게 되었습니다.","알겠습니다. 그렇게 하시죠.","서로 편안하게 인사할 수 있으면 좋겠습니다.","당신을 믿습니다. 다만 상대의 마음을 알았으니 경계는 함께 이야기하고 싶습니다."],"백지한":["그 사람이 당신을 그렇게 대하는 게 왜 이렇게 마음에 걸리는지 모르겠네요.","친구로만 지내고 싶지는 않습니다.","…알겠어요. 억지로 마음을 돌리게 할 생각은 없습니다.","다시 편하게 만날 수 있다면 좋겠네요.","그 사람이 당신한테 그런 마음을 갖고 있었다고요? …그럼 저도 신경은 쓰이겠죠."],"임하나":["저라면… 아, 죄송해요. 왜 자꾸 저를 대입하게 되는지.","저도 모르게 기다리고 있었어요. 친구 이상의 마음인 것 같아요.","네… 말씀해 주셔서 고마워요. 조금만 시간을 주세요.","다시 이야기할 수 있어서 정말 다행이에요.","저보다 그분에게 더 편하게 이야기하시는 건 아닐까… 조금 걱정돼요."],"차유리":["오, 나 지금 왜 그 사람 입장이 아니라 내 입장으로 생각했지?","친구로 지내는 것도 좋은데, 좋아하는 마음은 숨기기 어렵네요.","오케이. 마음은 마음이고, 선택은 당신 거죠.","다시 작업 얘기하고 맛있는 거 먹으러 가요.","친구인 건 존중해요. 그 사람이 선을 지키는지도 중요하겠죠."],"오세린":["으음, 당신이 행복했으면 좋겠는데 제 마음도 조금 복잡하네요.","아아, 저도 당신에게 특별한 사람이 되고 싶었던 모양이에요.","네. 마음을 알려 드린 것만으로 충분해요.","우리 다시 편안하게 차를 마실 수 있겠죠?","으음, 그분의 마음을 들으니 조금 불편하지만 당신과 이야기하고 싶어요."],"유지안":["와우, 나 왜 이렇게 그 사람 자리가 부럽지?","저요, 친구로만 좋아하는 게 아닌 것 같아요!","넵… 좀 속상하지만 억지로 할 수 있는 건 아니니까요.","예쓰! 다시 같이 뛰어요. 천천히 해도 돼요.","와우, 그 친구도 당신 좋아한다고요? 나도 더 잘 챙기고 싶어지는데요!"],"공재희":["헐, 왜 남의 연애 얘기 듣는데 내가 부럽지?","나 친구라고 생각했는데… 진짜 좋아하는 것 같음.","웅… 좀 슬프긴 한데 미안해하지는 마요.","다시 게임 같이 하면 안 됨? 친구로.","그 친구가 좋아한다고 했다고요? 나보다 더 편한 사람 되는 건 아니죠?"]};
function crushRecord(p){const r=friendshipRecord(p);return r.crush||(r.crush={status:'none',count:0,day:0,known:{},history:[]})}
function crushCanAwaken(p){const v=initSim(),r=crushRecord(p);return !vIsDating(p)&&friendAvailable(p)&&v.affection[p]>=45&&socialRecord(p).friendship>=5&&(r.status==='none'||r.status==='settled'&&v.day-r.day>=60)&&r.count>=1}
function crushCounsel(p,ev){const v=initSim(),r=crushRecord(p);r.count++;if(!crushCanAwaken(p))return;r.status='aware';r.day=v.day;r.known={};r.history.push({day:v.day,kind:'aware'});ev.crushAwake=true;feel(p,{longing:3});}
function crushGate(){const v=initSim();if(v.day>=365||[299,300].includes(v.day))return false;const p=people.find(q=>{const r=crushRecord(q);return !vIsDating(q)&&friendAvailable(q)&&r.status==='aware'&&v.day-r.day>=14&&v.affection[q]>=60});if(!p)return false;const r=crushRecord(p);if(!r.decision){r.decision=['서이준','임하나','오세린'].includes(p)?'hide':'tell';if(r.decision==='hide'){r.status='hidden';r.history.push({day:v.day,kind:'hide'});return false}}v.activeEvent={place:'home',person:p,day:v.day,description:'친구가 잠시 망설이다 말을 꺼냈다.',friendCrush:{kind:'confess'}};v.weekEnd=null;save();renderChoiceEvent();return true}
function crushDisclose(p){const v=initSim(),r=crushRecord(p);for(const q of lovers()){if(q===p||r.known[q])continue;r.known[q]=v.day;const t=phoneData().threads[q]||(phoneData().threads[q]=[]);t.push({day:v.day,booking:true,playerLine:p+'의 고백을 받았다는 사실을 이야기했다.',npcLine:friendCrushVoices[q][4],reply:1});feel(q,{jealousy:['백지한','공재희'].includes(q)?5:2});remember(q,'friendCrush:'+p+':'+v.day,p+'의 마음을 알게 됨')} }
function renderFriendCrush(ev){const v=initSim(),p=ev.person,r=crushRecord(p),o=ev.friendCrush,a=friendCrushVoices[p];$('progress').textContent='친구 이상의 마음';add(p,a[1]);if(o.answer){add(state.name,o.answer,true);add(p,o.reply);if(o.rejected&&lovers().length&&!o.disclosed){choiceButton('연인에게 고백받은 사실을 이야기한다',()=>{crushDisclose(p);o.disclosed=true;save();renderChoiceEvent()});}choiceButton('일정 계속하기',finishEvent);return}choiceButton('좋은 친구로 남고 싶어요.',()=>{if(o.answer)return;o.answer='좋은 친구로 남고 싶어요.';o.reply=a[2];o.rejected=true;r.status='cooling';r.day=v.day;r.decision=null;r.history.push({day:v.day,kind:'rejected'});save();renderChoiceEvent()});choiceButton('조금 더 생각할 시간을 주세요.',()=>{if(o.answer)return;o.answer='조금 더 생각할 시간을 주세요.';o.reply=a[2];r.day=v.day;r.status='hidden';save();renderChoiceEvent()});if(!lovers().length)choiceButton('저도 좋아해요. 우리 사귀어요.',()=>{if(o.answer)return;o.answer='저도 좋아해요. 우리 사귀어요.';o.reply=christmasLines[p][3];r.status='accepted';beginDating(p);save();renderChoiceEvent()});}
function crushNight(day){for(const p of people){const r=crushRecord(p);if(r.status==='cooling'&&day-r.day>=14){r.status='settled';r.day=day;r.count=0;r.history.push({day,kind:'friendAgain'});if(socialRecord(p).contact){const t=phoneData().threads[p]||(phoneData().threads[p]=[]);t.push({day,booking:true,playerLine:'',npcLine:friendCrushVoices[p][3],reply:1})}}}}

function friendshipRecord(p){const z=socialRecord(p);return z.friendRoute||(z.friendRoute={bond:false,outings:[],talks:[],lastMessage:0,history:[]})}
function friendAvailable(p){const a=aftermathRecord(p);return !vIsDating(p)&&crushRecord(p).status!=='cooling'&&(!a||a.status==='friend')&&socialRecord(p).contact&&relationshipTier(p)>=2}
function friendReadyRule(friendship,affection,outings,talks){return friendship>=8&&affection>=60&&outings>=2&&talks>=1}
function closeFriend(p){return !vIsDating(p)&&friendshipRecord(p).bond===true}
function friendCandidates(){return people.filter(closeFriend)}
function friendBookingSlots(p,day,checkBooking=true){
 if(!friendAvailable(p))return [];
 return dateBookingSlots(p,day,false,checkBooking);
}
function friendSlot(p,day){return preferredSlot(friendBookingSlots(p,day))}
function friendDates(p){const v=initSim();return Array.from({length:14},(_,i)=>v.day+i+1).filter(d=>d<=364&&!dateBook()[d]&&friendSlot(p,d)!==null)}
