function friendCheckMessage(p,day,thread){
 const pool=p==='차유리'?yuriFriendTexts:friendCheckTexts[p];
 const prefix=p==='차유리'?'friend:yuri:':'friend:topic:';
 const last=thread.findLast(m=>m.contextKey?.startsWith(prefix));
 const index=last?(Number(last.contextKey.split(':')[2])+1)%pool.length:day%pool.length;
 return {contextKey:prefix+index+':'+day,friendMessage:true,script:pool[index].slice()};
}
function friendPhone(p,day,t){if(!friendAvailable(p))return null;const r=friendshipRecord(p),z=socialRecord(p),a=friendshipVoices[p];if(z.friendship<2||day-(r.lastMessage||0)<8)return null;const last=r.outings[r.outings.length-1];if(last&&day-last.day<=3&&day>last.day){r.lastMessage=day;return {contextKey:'friend:after:'+last.day,friendMessage:true,script:[a[2],'지난번처럼 편하게 시간 보내요.','좋았어요. 또 놀아요.',a[4],'요즘 어떻게 지내요?',a[3]]}}if(day-(z.lastSeen||0)>=5){r.lastMessage=day;return friendCheckMessage(p,day,t)}return null}
function friendControls(p,root){const v=initSim();if(!friendAvailable(p)||v.finished)return;const r=friendshipRecord(p),a=friendshipVoices[p],d=document.createElement('div');d.className='stat-card';const h=document.createElement('p');h.textContent=(r.bond?'절친':'우정 쌓기')+' · 친구 외출 '+r.outings.length+'회 · 고민 나눔 '+r.talks.length+'회';d.append(h);
 const b=document.createElement('button');b.textContent='친구로 외출 약속 잡기';
 const pick=bookingPicker(d,v.day+1,Math.min(364,v.day+14),day=>friendBookingSlots(p,day),
  available=>{b.disabled=!available||!!v.running||!!v.activeEvent});
 b.onclick=()=>{if(!b.disabled&&bookFriend(p,pick.day(),pick.slot())){renderPhone();renderSim();syncSchedule()}};
 d.append(b);
 if(!v.running&&!v.activeEvent&&socialRecord(p).friendship>=3&&(!r.talks.length||v.day-r.talks[r.talks.length-1].day>=10)){const c=document.createElement('button');c.textContent='친구에게 고민 이야기하기';c.onclick=()=>{if(v.running||v.activeEvent)return;v.activeEvent={place:'home',person:p,day:v.day,description:'친구와 전화로 이야기를 나누었다.',friendScene:{kind:'talk'}};save();renderChoiceEvent()};d.append(c)}if(!r.bond&&friendReadyRule(socialRecord(p).friendship,v.affection[p],r.outings.length,r.talks.length)&&!v.running&&!v.activeEvent){const c=document.createElement('button');c.textContent='우리 우정에 대해 이야기하기';c.onclick=()=>{if(v.running||v.activeEvent)return;v.activeEvent={place:'home',person:p,day:v.day,description:'서로에게 어떤 친구인지 이야기하게 되었다.',friendScene:{kind:'bond'}};save();renderChoiceEvent()};d.append(c)}root.append(d)}
