const romanceBonusFields=["dateDepth","heartMoment","flirtOuting","springRain","seasonalDate","summerDate","autumnDate","winterDate","partnerComfort","coupleDate","loverAffection","afterglowMeeting","relationshipTouch","coupleHabit","playfulCouple","sensoryRomance","spontaneousInvite"];
function romanceBonusAllowed(ev,key){if(ev[key])return true;return romanceBonusFields.filter(k=>ev[k]).length<1}

function sensoryEligible(ev,p){const v=initSim(),a=sensoryRomanceScenes[p];if(!vIsDating(p)&&dateHistory(p).filter(x=>x.day<v.day).length<3)return false;if(!a||!v.running||!socialRecord(p).contact||platonicOnly(p)||relationshipTier(p)<2||!ev.answered)return false;const c=touchContext(p,v.day),z=socialRecord(p);if(c.conflicted||c.tired||z.sensorySeen||(!vIsDating(p)&&Math.max(z.interest||0,flirtRecord(p).interest||0)<5))return false;if(a.activity)return ev.activity===a.activity&&a.places.includes(ev.place)&&(p==='오세린'?v.slot===2&&['비','장맛비','소나기','흐림'].includes(weatherFor(v.day).name):v.slot===3);if(ev.dateEvent){if(ev.venue==='홈데이트')return p==='공재희';const venues={'강도윤':['디저트 투어','시장 구경','연화천 산책'],'한시우':['오락실','보드게임 카페'],'서이준':['영화관'],'정태오':['근교 나들이','시장 구경'],'백지한':['전시회','레스토랑','건축 산책'],'차유리':['사진 산책','전시회'],'유지안':['놀이공원','연화천 산책'],'공재희':['영화관','노래방']};return !!venues[p]?.includes(ev.venue||dateLines[p][0])}return a.places.includes(ev.place)&&v.slot>=2}
const spontaneousVisitScenes={"강도윤":["향 좋은 차","현관에서 모카가 반겼다. 도윤은 소매를 걷어 올리고 찻잎을 꺼냈다. 물이 끓는 소리와 함께 꽃향기가 번졌다.","하하, 사실 이거 같이 마시고 싶어서 사 둔 거예요. 혼자 마시면 맛을 설명할 사람도 없잖아요.","도윤 씨가 고른 향이 좋아요.","……다행이다. 오늘은 좀 오래 기억할 것 같네요.","모카랑도 조금 놀고 싶어요.","하하, 저보다 먼저 반겨 줬으니 섭섭하지 않게 해 줘야죠.","찻잔을 내려놓은 도윤이 소파 옆자리를 바라봤다.","조금만 옆에 앉아도 될까요?","도윤이 허락을 받고 앉았다. 소매가 가볍게 스치고 따뜻한 손이 옆에 놓였다.","……오늘은 제가 먼저 붙잡고 싶네요.","하하, 그럼 편한 자리에서 더 이야기해요.","다음에 또 놀러 와요. 오늘 정말 좋았어요."],"오세린":["비가 그칠 때까지","현관을 지나자 은은한 나무 향과 따뜻한 조명이 느껴졌다. 세린은 젖은 우산을 정리하고 깨끗한 수건을 건넸다.","아아, 들어오니까 빗소리가 더 잘 들리네요. 창가에 앉을까요?","창가에서 같이 비를 보고 싶어요.","좋아요. 오늘은 서두르지 않아도 되겠어요.","집이 정말 포근하네요.","후후, 그렇게 느끼셨다니 기쁘네요.","세린이 담요를 펼쳐 당신 옆에 앉을 자리를 살폈다.","으음, 괜찮으시면 같이 덮을까요?","허락을 받은 세린이 담요 한쪽을 덮었다. 빗소리 사이로 느린 숨과 옷감이 스치는 소리가 들렸다.","……비가 조금 더 내려도 좋겠네요.","그럼 각자 따뜻하게 덮고 있어요.","비가 잦아들었네요. 조심히 돌아가요."],"서이준":["조용한 밤","이준의 집에는 책과 작은 조명, 가지런히 정리된 신발이 보였다. 그는 조명을 한 단계 낮췄다.","…별건 없어요. 그냥 오늘은 조금 더 이야기하고 싶어서.","이렇게 조용한 곳도 좋아요.","…그래요? 다행이네요.","책 구경해도 돼요?","네. 마음에 드는 거 있으면 빌려 가요.","이준이 소파 옆을 비워 두고 당신을 바라봤다.","…여기 앉을래요?","허락을 받고 나란히 앉자 어깨 사이의 거리가 좁아졌다. 이준은 잠시 책을 덮었다.","…오늘은 읽던 페이지가 기억 안 나겠네요.","그래요. 거기 앉아도 잘 들려요.","…다음에 또 와요. 조심히 가고."],"한시우":["돌려주러 온 겉옷","시우가 집에 들어서며 빌려 준 겉옷을 받아 옷걸이에 걸었다. 따뜻한 공기와 세탁물 향이 났다.","아, 오늘은 정리 좀 해 놨어요. 놀리지 마요!","편하게 있는 모습이 좋아요.","히히, 그럼 다음엔 더 편하게 있을게요.","간식 뭐 있어요?","오, 취향 맞는데요? 과자부터 꺼내 올게요.","시우가 쿠션을 끌어안고 옆자리를 톡톡 두드렸다.","여기 앉아요. 조금 더 가까이 있어도 돼요?","허락을 받고 가까이 앉은 시우가 잠시 웃음을 멈췄다. 옷깃에서 익숙한 스킨 향이 났다.","와… 갑자기 말이 안 나오네. 이상하다.","오케이! 이 정도 거리도 좋아요.","오늘 재밌었어요. 도착하면 연락해요!"],"정태오":["정돈된 저녁","현관에 들어서자 가지런한 신발과 은은한 나무 향이 느껴졌다. 태오는 물을 가져왔다.","편하게 계십시오. 평소에는 손님이 많지 않습니다.","태오 씨 집에 오니까 새로운 느낌이에요.","…저도 그렇습니다. 조금 긴장되는군요.","물 한 잔 감사해요.","필요한 것이 있으면 말씀하십시오.","태오가 당신의 손을 바라보다 조용히 물었다.","손을 잠시 잡아도 되겠습니까?","허락을 받고 태오가 손을 잡았다. 따뜻하고 안정적인 온기가 전해졌다.","…조금 더 이렇게 있고 싶습니다.","알겠습니다. 편하게 이야기하시죠.","오늘 함께해 주셔서 감사합니다. 안전하게 돌아가십시오."],"백지한":["조용한 공간","지한이 현관을 열었다. 낮은 조명 아래 오래된 의자와 책들이 보였다.","제가 좋아하는 공간이에요. 오늘은 설명보다 그냥 같이 있어 보고 싶네요.","여기 있으니까 편안해요.","좋네요. 그 말을 듣고 싶었나 봐요.","저 의자 정말 멋있어요.","오, 눈썰미 좋으시네요. 오래 쓰고 있는 물건이에요.","지한이 느슨해진 셔츠 소매를 정리하고 빈자리를 가리켰다.","조금 가까이 앉아도 될까요?","허락을 받은 지한이 옆에 앉았다. 희미한 향수 향이 가까워졌다.","…이런 시간은 계획에 넣어 두기 어렵네요. 그래서 더 좋고요.","좋아요. 마주 보고 이야기하죠.","다음에도 제가 먼저 초대하고 싶네요."],"임하나":["작은 휴식","하나가 조심스럽게 문을 열고 쿠션을 정리했다. 깨끗한 빨래 향이 방 안에 남아 있었다.","저… 별건 없지만, 편하게 쉬어 가셨으면 좋겠어요.","하나 씨도 같이 쉬어요.","……네. 오늘은 저도 조금 쉬고 싶어요.","집 구경해도 돼요?","네! 제가 좋아하는 것부터 보여 드릴게요.","하나가 쿠션을 안고 당신을 바라봤다.","저… 옆에 앉아도 괜찮을까요?","고개를 끄덕이자 하나가 조심스레 다가왔다. 맞닿은 소매에서 온기가 느껴졌다.","……이렇게 가까이 있는 거, 좋네요.","네. 여기서 이야기해도 좋아요.","오늘 와 주셔서 정말 고마워요."],"차유리":["느슨한 오후","유리가 현관에서 머리끈을 풀었다. 창가로 늦은 햇살이 들어왔다.","오, 들어와요. 오늘은 아무것도 안 하는 날로 정했거든요.","같이 아무것도 안 해요.","좋다! 이런 약속 최고인데요?","창가에 앉아도 돼요?","오케이. 거기 햇빛 진짜 좋아요.","유리가 쿠션을 옆에 놓고 가까이 와도 되는지 물었다.","조금 붙어서 앉을래요?","허락을 받고 유리가 옆에 앉았다. 가벼운 화장품 향이 가까워졌다.","오… 이런 거 생각보다 떨리네요.","오케이, 편한 거리에서 쉬죠.","오늘 좋았다. 다음에 또 놀아요."],"유지안":["아무것도 안 하는 날","지안이 편한 실내복 차림으로 간식을 꺼냈다. 방에는 막 세탁한 담요가 놓여 있었다.","와우, 집에 오니까 갑자기 기운 빠진다. 우리 오늘 그냥 뒹굴까요?","좋아요. 같이 쉬어요.","아하하, 이렇게 편한 약속도 있어야죠!","간식부터 먹어요.","좋아요! 오늘 메뉴는 제가 고른 거예요.","지안이 담요를 펼치다가 당신을 바라봤다.","저기, 옆에 앉아도 돼요? 그냥 좀 붙어 있고 싶어서.","허락을 받고 지안이 옆에 앉았다. 평소보다 조용한 목소리로 웃었다.","……아, 이상하다. 오늘은 진짜 편한데 또 떨려요.","좋아요! 각자 편하게 있어요.","오늘 진짜 좋았다. 또 와요!"],"공재희":["화면을 끈 밤","재희가 화면을 끄고 간식 봉지를 열었다. 쿠션 사이에서 달콤한 샴푸 향이 희미하게 났다.","헐ㅋㅋ 오늘 방송 생각 하나도 안 남. 그냥 같이 놀아요.","오늘은 둘이 쉬어요.","웅ㅋㅋ 진짜 좋다.","간식부터 골라요.","ㅇㅋ! 맛있는 거 많음.","재희가 쿠션을 옆에 놓고 당신을 바라봤다.","근데 나 어깨에 기대도 됨?","허락을 받고 재희가 가볍게 머리를 기댔다. 잠시 말이 없어졌다.","……이거 좀 좋네. 오늘 시간 너무 빨리 감.","웅ㅋㅋ 쿠션 여기 둘게요.","집 도착하면 톡해요. 약속."]},spontaneousInviteVoices={"서이준":["…오늘은 조금 더 이야기하고 싶은데. 제 집에 잠깐 들를래요?","좋아요. 잠깐 들를게요.","…그럼 이쪽으로 가요.","그래요. 다음에 봐요."],"한시우":["아, 집에 간식 엄청 많거든요. 잠깐 들러서 먹고 갈래요?","좋아요. 잠깐 놀다 갈게요.","오예! 그럼 가요!","오케이! 다음에 놀러 와요."],"정태오":["시간이 괜찮으시다면 제 집에서 잠시 쉬어 가시겠습니까?","좋아요. 잠깐 쉬고 갈게요.","알겠습니다. 이쪽입니다.","알겠습니다. 조심히 돌아가십시오."],"백지한":["근처에 제 집이 있는데. 잠깐 들러서 이야기하고 가실래요?","좋아요. 조금 더 같이 있어요.","좋죠. 이쪽으로 가요.","좋아요. 다음에 초대할게요."],"임하나":["저… 혹시 시간 괜찮으면 제 집에서 조금 쉬고 가실래요?","좋아요. 잠깐 들를게요.","……네! 이쪽이에요.","네. 다음에 또 봐요."],"차유리":["오, 우리 집에서 잠깐 쉬었다 갈래요? 오늘은 작업도 안 해요.","좋아요. 조금 쉬었다 갈게요.","좋다! 편하게 와요.","오케이. 다음에 놀러 와요."],"유지안":["아, 그냥 헤어지기 아쉽다. 우리 집에서 간식 먹고 갈래요?","좋아요. 잠깐 놀다 갈게요.","예쓰! 맛있는 거 많아요.","좋아요! 다음에 와요."],"공재희":["헐 벌써 감? 우리 집에서 조금 더 놀다 가면 안 됨?","좋아요. 조금 더 놀아요.","웅ㅋㅋ 가자.","ㅇㅋ. 다음에 또 봐요."],"강도윤":["시간 괜찮으시면 집에서 차 한 잔 더 마시고 가실래요?","좋아요. 같이 차 마셔요.","하하, 그럼 이쪽으로 가요.","좋아요. 다음에 마셔요."],"오세린":["으음, 괜찮으시면 저희 집에서 조금 쉬어 가실래요?","좋아요. 잠깐 들를게요.","아아, 그럼 같이 가요.","네. 조심히 돌아가요."]};
function spontaneousVisitEligible(ev,p){const v=initSim(),z=socialRecord(p),c=touchContext(p,v.day);return !!(v.running&&ev.answered&&!platonicOnly(p)&&vIsDating(p)&&relationshipTier(p)>=3&&v.day-coupleRecord(p).since>=7&&!c.tired&&!c.conflicted&&!z.spontaneousVisitDay&&ev.venue!=='홈데이트'&&sensoryExtraTime(ev,p))}
function renderSpontaneousInvite(ev,p){if(!romanceBonusAllowed(ev,'spontaneousInvite'))return false;if(!ev.spontaneousInvite&&(ev.sensoryRomance?.answer?.warm||ev.spontaneousVisit))return false;const v=initSim(),a=spontaneousInviteVoices[p];if(!ev.spontaneousInvite){if(!spontaneousVisitEligible(ev,p))return false;ev.spontaneousInvite={};save()}const o=ev.spontaneousInvite;add(p,a[0]);if(o.answer){add(state.name,o.answer.label,true);add(p,o.answer.reply);return false}for(const [label,reply,yes] of [[a[1],a[2],true],['오늘은 먼저 돌아갈게요.',a[3],false]])choiceButton(label,()=>{if(o.answer)return;o.answer={label,reply,yes};if(yes){ev.spontaneousVisit={source:'invite',step:0};}else socialRecord(p).spontaneousVisitDay=v.day;save();renderChoiceEvent()});return true}
function renderSpontaneousVisit(ev,p){const v=initSim(),o=ev.spontaneousVisit;let a=spontaneousVisitScenes[p];if(!o||!a)return false;if(p==='한시우'&&o.source!=='sensory'){a=[...a];a[0]='편안한 방문';a[1]='시우가 현관에서 당신을 맞았다. 따뜻한 공기와 세탁물 향이 났다.'}if(p==='오세린'&&o.source!=='sensory'){a=[...a];a[0]='창가의 휴식';a[1]='현관을 지나자 은은한 나무 향과 따뜻한 조명이 느껴졌다.';a[2]='아아, 들어오세요. 창가에 앉을까요?';a[3]='창가에서 같이 쉬어요.';a[9]='허락을 받은 세린이 담요 한쪽을 덮었다. 가까이서 느린 숨과 옷감이 스치는 소리가 들렸다.';a[10]='……이렇게 있으니 참 편안하네요.';a[12]='오늘 와 주셔서 고마워요. 조심히 돌아가요.'}$('where').textContent=p+'의 집';$('progress').textContent='즉흥 방문 · '+a[0];add('이야기',a[1]);add(p,a[2]);if(!o.first){for(const [label,reply] of [[a[3],a[4]],[a[5],a[6]],['오늘은 이만 돌아갈게요.',a[12]]])choiceButton(label,()=>{if(o.first)return;o.first={label,reply,leave:label==='오늘은 이만 돌아갈게요.'};save();renderChoiceEvent()});return true}add(state.name,o.first.label,true);add(p,o.first.reply);if(!o.first.leave){add('이야기',a[7]);add(p,a[8]);if(!o.second){for(const [label,reply,near] of [['좋아요. 가까이 있어요.',a[10],true],['오늘은 편하게 이야기만 해요.',a[11],false],['이제 돌아갈게요.',a[12],false]])choiceButton(label,()=>{if(o.second)return;o.second={label,reply,near};save();renderChoiceEvent()});return true}add(state.name,o.second.label,true);if(o.second.near)add('이야기',a[9]);add(p,o.second.reply)}if(!o.done){o.done=true;const z=socialRecord(p);z.spontaneousVisitDay=v.day;z.lastTogether=v.day;z.lastSeen=v.day;feel(p,{security:2});if(o.second?.near)v.affection[p]=Math.min(999,v.affection[p]+2);remember(p,'spontaneousVisit',o.first.label+(o.second?' / '+o.second.label:''));writeJournal(p+' · 즉흥 방문');if(v.running)v.running.notes.push(p+'의 집에 잠시 방문');save()}add('이야기','함께 보낸 시간을 마무리하고 집으로 돌아갔다.');choiceButton('일정 계속하기',finishEvent);return true}

function sensoryExtraTime(ev,p){const v=initSim();return v.running&&v.running.plan.slice(v.running.slot+1).every(a=>a==='휴식')&&!npcLifeBusy(p,v.day,3)}
function renderSensoryRomance(ev,p){if(!romanceBonusAllowed(ev,'sensoryRomance'))return false;const v=initSim(),a=sensoryRomanceScenes[p];if(!ev.sensoryRomance){if(!sensoryEligible(ev,p))return false;ev.sensoryRomance={step:0};save()}const o=ev.sensoryRomance;add('이야기',a.intro);add(p,a.line);if(o.approach===undefined){for(const [label,k] of [['상대의 행동에 응한다',1],['조금 거리를 유지한다',0]])choiceButton(label,()=>{if(o.approach!==undefined)return;o.approach=k;save();renderChoiceEvent()});return true}add(state.name,o.approach?'상대의 행동에 응한다':'조금 거리를 유지한다',true);if(o.approach){let near=a.near;if(p==='임하나'&&seasonInfo(v.day).index===1)near=near.replace('소매를 조심스레 정리하고 살짝 받쳐 들었다','손목을 조심스레 받쳐 들었다');add('이야기',near);add(p,a.ask)}else{add(p,a.neutralReply)}if(o.answer){add(state.name,o.answer.label,true);add(p,o.answer.reply);if(o.answer.warm&&['강도윤','오세린'].includes(p)){if(!ev.spontaneousVisit){ev.spontaneousVisit={source:'sensory',step:0};save()}return renderSpontaneousVisit(ev,p)}if(o.answer.end)add('이야기',o.answer.end);return false}const extend=['강도윤','오세린','백지한'].includes(p);const opts=o.approach?[[a.yes,a.reply,a.end,1],[a.neutral,a.neutralReply,'',0],[a.later,a.laterReply,'',0]]:[[a.neutral,a.neutralReply,'',0],[a.later,a.laterReply,'',0]];for(const [label,reply,end,warm] of opts){if(warm&&extend&&!sensoryExtraTime(ev,p))continue;choiceButton(label,()=>{if(o.answer)return;o.answer={label,reply,end,warm};const z=socialRecord(p);z.sensorySeen=v.day;z.lastTogether=v.day;if(warm){v.affection[p]=Math.min(999,v.affection[p]+2);if(!vIsDating(p))z.interest++;if(p==='강도윤')flirtRecord(p).touches.push({day:v.day,type:'손잡기',scene:'sensory'});if(extend&&v.running){v.running.plan=v.running.plan.map((x,i)=>i>v.running.slot?'휴식':x);v.running.notes.push(p+'와 조금 더 시간을 보냈다.')}}feel(p,{security:1});remember(p,'sensoryRomance',label+' / '+reply);writeJournal(p+' · '+a.title);save();renderChoiceEvent();renderSim()})}return true}

function renderLoverAffection(ev,p){if(!romanceBonusAllowed(ev,'loverAffection'))return false;const v=initSim(),c=coupleRecord(p);if(!ev.loverAffection){const i=loverAffectionCandidate(p,v.day);if(i<0)return false;ev.loverAffection={i,since:c.since};save()}const o=ev.loverAffection,a=loverAffectionScenes[p][o.i];add('이야기',a[1]);add(p,a[2]);if(o.answer){add(state.name,o.answer.label,true);add(p,o.answer.reply);return false}for(const [label,reply,warm] of [[a[3],a[4],true],[a[5],a[6],false]])choiceButton(label,()=>{if(o.answer||!vIsDating(p)||coupleRecord(p).since!==o.since)return;o.answer={label,reply,warm};c.affectionScenes=c.affectionScenes||{};c.affectionScenes[o.i]=v.day;c.history.push({day:v.day,stage:'affection:'+o.i,label,reply});feel(p,{security:2});if(warm)v.affection[p]=Math.min(999,v.affection[p]+2);remember(p,'loverAffection:'+o.i,label+' / '+reply);writeJournal(p+' · '+a[0]);save();renderChoiceEvent();renderSim()});return true}

function renderCoupleDate(ev,p){if(!romanceBonusAllowed(ev,'coupleDate'))return false;const v=initSim(),day=ev.day||v.day;if(!ev.coupleDate){const stage=coupleStage(p,day);if(!stage||touchContext(p,day).conflicted)return false;ev.coupleDate={stage};save()}const o=ev.coupleDate,a=coupleVoices[p][o.stage==='early'?0:1];add('이야기',a[0]);add(p,a[1]);if(o.answer){add(state.name,o.answer.label,true);add(p,o.answer.reply);return false}for(const [label,reply,i] of [[a[2],a[3],0],[a[4],a[5],1]])choiceButton(label,()=>{if(o.answer)return;o.answer={label,reply};const r=coupleRecord(p);r.seen[o.stage]=day;r.history.push({day,stage:o.stage,choice:i,label,reply});feel(p,{security:2});remember(p,'couple:'+o.stage,label+' / '+reply);writeJournal(p+' · '+(o.stage==='early'?'연애의 시작':'각자의 일상'));save();renderChoiceEvent();renderSim()});return true}
function privateEveningBlock(p,day){
 if(!vIsDating(p))return '서로 연인이 된 뒤에 열리는 장면이에요.';
 const age=day-coupleRecord(p).since;
 if(age<14)return '지금은 교제 D+'+Math.max(0,age)+'예요. 함께 밤을 보내는 선택은 D+14부터 열려요.';
 const c=touchContext(p,day);
 if(c.conflicted)return memoryFor(p).feelings.hurt>=5?'상대에게 아직 서운한 마음이 남아 있어요.':'두 사람 사이에 아직 풀지 않은 일이 있어요.';
 if(relationshipBoundaryLine(p,day))return '지난번에 스킨십에서 거리를 두기로 한 걸 상대가 기억하고 있어요.';
 if(c.tired)return '상대가 오늘은 피곤해요. 다음에 컨디션이 좋은 날 다시 만나요.';
 if(c.security<5)return '상대가 편안함을 느낄 시간이 조금 더 필요해요.';
 return '';
}
function privateEveningReady(p,day){return !privateEveningBlock(p,day)}
function overnightReady(p,day,sharedHome=false){const v=initSim();if(v.romance[p]!=='dating'||day>=364||v.overnightPending||!v.running||!v.running.plan.slice(v.running.slot+1).every(a=>a==='휴식')||dateBook()[day+1]?.slot===0||[299,300].includes(day+1)||npcLifeBusy(p,day+1,0))return false;const r=coupleRecord(p);return privateEveningReady(p,day)&&
 (sharedHome||!!r.seen.early&&!!r.seen.steady&&!r.seen.overnight&&dateHistory(p).filter(x=>x.day>r.since&&x.day<=day).length>=2)}
function recordOvernightStay(p,day){
 const v=initSim();
 v.overnightPending={p,day};
 coupleRecord(p).seen.overnight=day;
 v.running.notes.push(nameWith(p)+' 함께 보내는 밤');
 remember(p,'couple:overnight','함께 밤을 보내기로 함');
}
function renderOvernight(ev,p,warm){
 const v=initSim(),day=ev.day||v.day,o=ev.overnight,a=coupleVoices[p][2];
 if(o?.answer!==undefined){
  add('이야기',a[0]);add(p,a[1]);
  add(state.name,o.answer===1?'좋아요. 오늘 밤 함께 보내요.':'오늘은 각자 쉬고 싶어요.',true);add(p,a[o.answer===1?2:3]);
  if(o.answer===1){add('이야기','두 사람은 오늘 밤을 함께 보내기로 했다.');renderOvernightCloseness(p);choiceButton('일정 계속하기',finishEvent);return true}
  return false;
 }
 const regular=warm&&v.running?.slot===3&&(ev.slot??3)===3&&privateEveningReady(p,day);
 if(!o&&!regular&&(!ev.homeTouchText||!overnightReady(p,day)))return false;
 ev.overnight=o||{regular};
 return renderEveningHomeDate(ev,p,ev.overnight,!ev.overnight.regular);
}
