function renderCoupleMorning(ev){const v=initSim(),p=ev.person,a=coupleVoices[p][2],day=ev.day??v.day;
 $('progress').textContent='연인의 아침';
 add('이야기',ev.loveNight?loveNightScene(p,ev.loveNight,ev.loveRoute).morning:a[4]);
 const greet=addressTurn(p,day)%3===0&&agreedAddress(p,'npc',day);
 if(!ev.loveNight)add(p,greet?spokenCall(p,'npc',day,a[5]):a[5]);
 else if(greet)add(p,spokenCall(p,'npc',day,wakingVoices[p][speechRegisterIndex(p,'npc',day)]));
 if(ev.morningAnswer){add(state.name,ev.morningAnswer.label,true);add(p,ev.morningAnswer.reply);choiceButton('오늘 하루 시작하기',finishEvent);return}for(const [label,reply,i] of [[a[6],a[7],0],[a[8],a[9],1]])choiceButton(label,()=>{if(ev.morningAnswer)return;ev.morningAnswer={label,reply};coupleRecord(p).history.push({day:v.day,stage:'morning',choice:i,label,reply});socialRecord(p).lastTogether=v.day;feel(p,{security:2});remember(p,'couple:morning',label+' / '+reply);writeJournal(p+' · 함께 맞이한 아침');save();renderChoiceEvent();renderSim()})}

